import{a as o}from"./shared-CAKwAg2C.js";const n={"LEARN HOW THE INTERNET WORKS":"איך האינטרנט עובד","NOW LEARNING":"לומדים עכשיו","OSI LAYER":"שכבת OSI","LEARNING PROGRESS":"התקדמות בלמידה",COMPLETE:"הושלמו","IN PROGRESS":"בתהליך","{pct}% complete":"{pct}% הושלמו","DESIGNED BY":"עיצוב","Dilum Sanjaya on X":"Dilum Sanjaya ב־X","Layer {n}: {name}":"שכבה {n}: {name}",Physical:"השכבה הפיזית","Data Link":"שכבת קו הנתונים",Network:"שכבת הרשת",Transport:"שכבת התעבורה",Session:"שכבת השיחה",Presentation:"שכבת התצוגה",Application:"שכבת היישום","OVERVIEW · {n} STEPS":"סקירה · {n} שלבים","STEP {n}/{total} · {title}":"שלב {n}/{total} · {title}","LESSON COMPLETE":"השיעור הושלם",PROTOCOLS:"פרוטוקולים",Protocols:"פרוטוקולים",Language:"שפה",Theme:"ערכת נושא","Light mode":"מצב בהיר","Dark mode":"מצב כהה","INTERNET PROTOCOLS":"פרוטוקולי אינטרנט",More:"עוד","Close the protocol list":"סגירת רשימת הפרוטוקולים","Close (Esc)":"סגירה (Esc)",ALL:"הכול",CORE:"בסיס",APPLICATION:"יישומים",SECURITY:"אבטחה",NETWORK:"רשת",SEQUENCE:"רצף",View:"תצוגה","Switch view (V)":"החלפת תצוגה (V)","Network diagram":"תרשים רשת","Sequence diagram":"תרשים רצף","STEP {n}":"שלב {n}","PROTOCOL OVERVIEW":"סקירת הפרוטוקול","STEP DETAILS":"פרטי השלב","LESSON SUMMARY":"סיכום השיעור",OVERVIEW:"התחלה",ACTIVE:"פעיל","STEP {n} OF {total}":"שלב {n} מתוך {total}","PACKET {n} OF {total}":"חבילה {n} מתוך {total}","PACKETS {from}–{to} OF {total}":"חבילות {from}–{to} מתוך {total}","{n} LOST":"{n} אבדו","1 LOST":"אחת אבדה",ENCRYPTED:"מוצפן","LOST ON THE WAY":"אבדה בדרך","PACKET FLOW":"זרימת חבילות","Colour key":"מקרא צבעים","Playback speed":"מהירות הפעלה","Previous step (←)":"השלב הקודם (→)","Previous step":"השלב הקודם","Play / pause (Space)":"הפעלה / השהיה (רווח)",PLAY:"הפעלה",PAUSE:"השהיה",REPLAY:"שוב",STEP:"צעד","One packet at a time":"חבילה אחת בכל פעם",RESET:"איפוס",Reset:"איפוס","Back to the overview (Esc)":"חזרה לסקירה (Esc)","NO.":"מס׳",TIME:"זמן",SOURCE:"מקור",DESTINATION:"יעד",PROTOCOL:"פרוטוקול",INFO:"מידע",SIZE:"גודל","No packets on the wire yet.":"עדיין אין חבילות על הקו.",LOST:"אבדה","Packet inspector":"בודק חבילות","Previous packet":"החבילה הקודמת","Previous packet (←)":"החבילה הקודמת (→)","Next packet":"החבילה הבאה","Next packet (→)":"החבילה הבאה (←)",Close:"סגירה","E.G.":"לדוגמה","an example value: it differs in every real capture":"ערך לדוגמה: שונה בכל לכידה אמיתית","bytes the lesson can’t show: encrypted, random, or a file’s contents":"בתים שהשיעור לא יכול להציג: מוצפנים, אקראיים או תוכן של קובץ",BYTES:"בתים","{n} in this frame":"{n} במסגרת הזו","This row stands for {n} TCP segments carrying a {size}-byte message; the first segment is shown":"שורה זו מייצגת {n} מקטעי TCP שנושאים הודעה של {size} בתים; מוצג המקטע הראשון","This packet was lost on the way":"החבילה הזו אבדה בדרך",Padding:"ריפוד","192.168.1.10/24 · 24 H LEASE":"192.168.1.10/24 · חכירה ל־24 שעות","2 SEGMENTS":"2 מקטעים","3 SEGMENTS":"3 מקטעים","3 DATAGRAMS":"3 דאטגרמות","4 DATAGRAMS":"4 דאטגרמות","203.0.113.10 IS NOT LOCAL":"203.0.113.10 אינו מקומי","250 QUEUED":"250 בתור",ANSWER:"תשובה","APP COVERS THE 20 MS GAP":"היישום מכסה את הפער של 20 ms","APP DATA":"נתוני יישום","ARP REPLY":"תשובת ARP","ARP REQUEST":"בקשת ARP","ARRIVED WITH TTL 116":"הגיעה עם TTL 116","AUTH FAILURE":"AUTH נכשל","At QUIT":"ב־QUIT","CACHED · TTL 3600 S":"במטמון · TTL 3600 ש׳","CERTIFICATE VALID":"התעודה תקפה","CHAIN LEADS TO A TRUSTED ROOT":"השרשרת מובילה לשורש מהימן","CHANNEL OPEN":"פתיחת ערוץ",CONFIRMED:"אושר","DNS QUERY":"שאילתת DNS","DNS REPLY":"תשובת DNS","DUP ACK":"ACK כפול","EACH KEY IS ITS OWN PACKET":"כל מקש בחבילה משלו",ECHO:"הד","ECHO REPLY":"תשובת הד","ECHO REQUEST":"בקשת הד",ENTER:"Enter","FRAME 7 LOST · NOT RESENT":"מסגרת 7 אבדה · לא נשלחת שוב","HOP 2 · 198.51.100.1":"קפיצה 2 · 198.51.100.1","HOST KEY MATCHES KNOWN_HOSTS":"מפתח המארח תואם ל־known_hosts","IN BOB’S MAILBOX":"בתיבת הדואר של Bob","IP PACKET":"חבילת IP",MESSAGE:"הודעה","MESSAGE 1 DELETED":"הודעה 1 נמחקה","NEW MAIL ARRIVED":"הגיע דואר חדש","NO IP ADDRESS YET":"עדיין אין כתובת IP","NOT IN CACHE":"לא במטמון","OFFER KEY":"הצגת מפתח",OUTPUT:"פלט","PASSWORD IN PLAIN TEXT":"סיסמה בטקסט גלוי",REFERRAL:"הפניה",REPLY:"תשובה",RESEND:"שליחה חוזרת","SEGMENT 1 LOST":"מקטע 1 אבד","SFTP or FTPS":"SFTP או FTPS","SFTP, or FTPS (FTP + TLS)":"SFTP, או FTPS (FTP + TLS)","SHARED SECRET COMPUTED":"הסוד המשותף חושב",SIGNED:"חתום","STILL ON SERVER · \\SEEN":"עדיין בשרת · \\Seen",SUCCESS:"הצלחה","TIME EXCEEDED":"חריגת זמן","TIME=34MS TTL=52":"TIME=34MS TTL=52",UNREACHABLE:"לא ניתן להגיע",VERSION:"גרסה","VOICE 1":"קול 1","+OK or -ERR":"+OK או -ERR",".com Server":"שרת .com",Authoritative:"שרת מוסמך","Log In":"התחברות",Key:"מפתח",Why:"למה",End:"סוף","MACs, in":"MAC, נכנס",Internet:"אינטרנט",Router:"נתב","Router 192.168.1.1":"נתב 192.168.1.1","Router: 192.168.1.1":"נתב: 192.168.1.1",Routers:"נתבים",Hardware:"חומרה",Audio:"אודיו",Ping:"Ping",Cookie:"Cookie","Magic cookie":"Magic cookie",Visible:"מה גלוי",Tickets:"כרטיסים","4, 20 bytes":"4, 20 בתים","20–60 bytes":"20–60 בתים","20–60 bytes (IPv4)":"20–60 בתים (IPv4)","8 bytes (TCP: 20+)":"8 בתים (TCP: 20+)","32 bytes (Windows)":"32 בתים (Windows)","1,460 bytes (MSS)":"1,460 בתים (MSS)","78 bytes (seq 1–78)":"78 בתים (seq 1–78)","bytes 1461–2920":"בתים 1461–2920","text/html, 12.2 KB":"text/html, 12.2 KB","1026 (× 256 = 262,656 bytes)":"1026 (× 256 = 262,656 בתים)","501 (× 128 = 64,128 bytes)":"501 (× 128 = 64,128 בתים)","X25519MLKEM768 (1,216 bytes), X25519":"X25519MLKEM768 (1,216 בתים), X25519","X25519MLKEM768 (1,120 bytes)":"X25519MLKEM768 (1,120 בתים)",'"abcdefghijklmnopqrstuvwabcdefghi" (32 bytes)':'"abcdefghijklmnopqrstuvwabcdefghi" (32 בתים)','"hello, anyone here" (18 bytes)':'"hello, anyone here" (18 בתים)',"32 bits (IPv4), 128 (IPv6)":"32 סיביות (IPv4), 128 (IPv6)","64 → 52 (12 routers)":"64 ← 52 (12 נתבים)","52 (64 − 12 routers)":"52 (64 − 12 נתבים)","1 (Ethernet)":"1 (Ethernet)","report.pdf, 4,000 bytes":"report.pdf, 4,000 בתים","1190 bytes (sntrup761 1,158 + X25519 32)":"1190 בתים (sntrup761 1,158 + X25519 32)","RTP + audio":"RTP + שמע"},i={"Hypertext Transfer Protocol":"פרוטוקול העברת היפרטקסט","HTTP Secure":"HTTP מאובטח","Transmission Control Protocol":"פרוטוקול בקרת שידור","User Datagram Protocol":"פרוטוקול דאטגרמות משתמש","Internet Protocol":"פרוטוקול האינטרנט","Domain Name System":"מערכת שמות המתחם","Dynamic Host Configuration":"הגדרת מארח דינמית","Internet Control Message":"הודעות בקרה באינטרנט","Simple Mail Transfer Protocol":"פרוטוקול העברת דואר פשוט","Post Office Protocol v3":"פרוטוקול סניף הדואר v3","Internet Message Access":"גישה להודעות אינטרנט","File Transfer Protocol":"פרוטוקול העברת קבצים","Secure Shell":"מעטפת מאובטחת","Transport Layer Security":"אבטחת שכבת התעבורה",Internet:"אינטרנט",Client:"לקוח",Router:"נתב","DNS Resolver":"רזולבר DNS","Web Server":"שרת ווב","Root Server":"שרת שורש",".com TLD Server":"שרת .com (TLD)","Authoritative Server":"שרת מוסמך","Mail Server":"שרת דואר","Web Communication":"תקשורת ווב",Request:"בקשה",Response:"תגובה","Data ACKs not shown":"אישורי ACK לנתונים לא מוצגים","HTTP is the protocol of the web: a client asks for a resource, such as an HTML page, and the server answers with a status code, headers and usually a body. Every exchange is one request and one response, written as readable text in HTTP/1.1.":"HTTP הוא הפרוטוקול של הרשת: לקוח מבקש משאב, למשל דף HTML, והשרת עונה עם קוד מצב, כותרות ובדרך כלל גוף. כל חילופי מסרים הם בקשה אחת ותגובה אחת, שנכתבות ב־HTTP/1.1 כטקסט קריא.",Layer:"שכבה","Application (Layer 7)":"יישום (שכבה 7)","Default Port":"פורט ברירת מחדל",Transport:"שכבת התעבורה","Data Format":"פורמט הנתונים","Text (headers + optional body)":"טקסט (כותרות + גוף אופציונלי)","Common Methods":"שיטות נפוצות","Defined In":"מוגדר ב־","Page delivered":"הדף נמסר","One request, one response":"בקשה אחת, תגובה אחת","In under a tenth of a second the laptop looked up an address, opened a TCP connection and exchanged one HTTP request and response, all of it readable by anyone on the path. Press REPLAY to watch it again.":"בפחות מעשירית שנייה המחשב הנייד מצא כתובת, פתח חיבור TCP והחליף בקשת HTTP אחת ותגובה אחת, וכל זה היה קריא לכל מי שנמצא בדרך. לחצו על ״שוב״ כדי לצפות שוב.","Round trips":"סבבים הלוך ושוב","Total time":"זמן כולל","Page size":"גודל הדף","Sent as 9 TCP segments":"נשלח ב־9 מקטעי TCP","Client Request":"בקשת הלקוח","Browser prepares the request":"הדפדפן מכין את הבקשה","You open http://www.example.com. The browser will send a GET request, but packets travel to IP addresses, not names, so first it needs the server’s address. (Browsers now try https:// first; this is the plain version.)":"אתם פותחים את http://www.example.com. הדפדפן ישלח בקשת GET, אבל חבילות נשלחות לכתובות IP ולא לשמות, ולכן קודם הוא צריך את כתובת השרת. (כיום דפדפנים מנסים קודם https://; זו הגרסה הלא מוצפנת.)",Method:"שיטה","Next hop":"הקפיצה הבאה","Router 192.168.1.1":"נתב 192.168.1.1","DNS Resolution":"פענוח DNS","Finds the server’s IP address":"מוצא את כתובת ה־IP של השרת","The laptop asks the DNS server it was given by DHCP, 8.8.8.8, for the address of www.example.com. The query goes over UDP port 53 and the answer is an A record with the IPv4 address. (On a network with IPv6 it would also ask for an AAAA record.)":"המחשב הנייד שואל את שרת ה־DNS שקיבל מ־DHCP (8.8.8.8) מה הכתובת של www.example.com. השאילתה נשלחת ב־UDP לפורט 53, והתשובה היא רשומת A עם כתובת ה־IPv4. (ברשת עם IPv6 הוא היה מבקש גם רשומת AAAA.)",Resolver:"רזולבר","8.8.8.8 (had it cached)":"8.8.8.8 (היה במטמון)","UDP, port 53":"UDP, פורט 53",Answer:"תשובה","TCP Connection":"חיבור TCP","Establishes a reliable link":"יוצר חיבור אמין","HTTP runs on top of TCP. Before any page data moves, the laptop and the server open a connection to port 80 with a three-way handshake: SYN, SYN-ACK, ACK.":"HTTP פועל מעל TCP. לפני שנתוני הדף מתחילים לעבור, המחשב הנייד והשרת פותחים חיבור לפורט 80 בלחיצת יד משולשת: SYN, SYN-ACK, ACK.","Server port":"פורט השרת","Client port":"פורט הלקוח",Handshake:"לחיצת יד","HTTP Exchange":"חילופי HTTP","Request and response messages":"הודעות בקשה ותגובה","The browser sends a GET request with a Host header. The server answers 200 OK with the HTML in the body: 12.2 KB, too big for one packet, so TCP splits it into 9 segments of up to 1460 bytes (drawn here as one).":"הדפדפן שולח בקשת GET עם כותרת Host. השרת עונה 200 OK עם ה־HTML בגוף: 12.2 KB, גדול מדי לחבילה אחת, ולכן TCP מחלק אותו ל־9 מקטעים של עד 1460 בתים (מצוירים כאן כאחד).",Status:"סטטוס",Body:"גוף","Sent as":"נשלח כ־","12.2 KB in 9 segments":"12.2 KB ב־9 מקטעים","Page Rendering":"הצגת הדף","Browser displays the content":"הדפדפן מציג את התוכן","The browser parses the HTML and paints the page. Linked CSS, images and scripts would each start more requests just like this one, reusing the open connection where they can.":"הדפדפן מנתח את ה־HTML ומצייר את הדף. כל קובץ CSS, תמונה או סקריפט מקושרים יפתחו בקשות נוספות בדיוק כמו זו, וישתמשו שוב בחיבור הפתוח כשאפשר.",Document:"מסמך",Connection:"חיבור","Kept open for reuse":"נשאר פתוח לשימוש חוזר","Seen on the laptop’s home network":"כפי שנראה ברשת הביתית של המחשב הנייד",Destination:"יעד","The router: anything beyond the home network goes to it first.":"הנתב: כל מה שיוצא מהרשת הביתית עובר קודם דרכו.",Source:"מקור","The laptop’s network card.":"כרטיס הרשת של המחשב הנייד.",Type:"סוג","What the frame carries.":"מה המסגרת נושאת.","Version, header length":"גרסה, אורך כותרת","IPv4, with no options.":"IPv4, ללא אפשרויות.","Priority and congestion marks; 0 means ordinary traffic.":"סימוני עדיפות ועומס; 0 פירושו תעבורה רגילה.","Total length":"אורך כולל","This header and everything inside it.":"הכותרת הזו וכל מה שבתוכה.",Identification:"זיהוי","Lets the receiver reassemble the pieces if the packet gets split.":"מאפשר למקבל להרכיב מחדש את החלקים אם החבילה פוצלה.",Flags:"דגלים",none:"אין","Routers may split it if a link is too small.":"נתבים רשאים לפצל אותה אם קישור כלשהו קטן מדי.","Time to live":"זמן חיים","Windows starts at 128.":"Windows מתחיל ב־128.",Protocol:"פרוטוקול","Header checksum":"סכום ביקורת של הכותרת","Covers this header only; every router recomputes it after lowering the TTL.":"מכסה רק את הכותרת הזו; כל נתב מחשב אותו מחדש אחרי שהוא מוריד את ה־TTL.","Source port":"פורט מקור","Destination port":"פורט יעד",Length:"אורך","UDP header and data. That is all of UDP: no numbering, no acknowledgements.":"כותרת UDP ונתונים. זה כל UDP: בלי מספור ובלי אישורים.",Checksum:"סכום ביקורת","Covers the header, the data and the IP addresses.":"מכסה את הכותרת, הנתונים וכתובות ה־IP.","Transaction ID":"מזהה טרנזקציה","Picked at random; the answer must carry the same one.":"נבחר באקראי; התשובה חייבת לשאת את אותו מזהה.","0x0100: query, RD (recursion desired)":"0x0100: שאילתה, RD (רקורסיה רצויה)",Questions:"שאלות",Answers:"תשובות","Authority records":"רשומות סמכות","Additional records":"רשומות נוספות",Question:"שאלה","www.example.com, type A, class IN":"www.example.com, סוג A, מחלקה IN","The laptop.":"המחשב הנייד.","The router’s side facing the home network.":"הצד של הנתב הפונה לרשת הביתית.","Started at 128; 10 routers on the way each took 1.":"התחיל ב־128; כל אחד מ־10 הנתבים בדרך הוריד 1.","0x8180: response, RD (recursion desired), RA (recursion available)":"0x8180: תגובה, RD (רקורסיה רצויה), RA (רקורסיה זמינה)","DF (don’t fragment)":"DF (אסור לפצל)","Routers must not split it; if it’s too big they report back instead.":"אסור לנתבים לפצל אותה; אם היא גדולה מדי הם מדווחים על כך בחזרה.","Picked by the laptop’s system for this connection.":"נבחר על ידי המערכת של המחשב הנייד לחיבור הזה.","Sequence number":"מספר רצף","This side’s starting number. Shown as 0; the real one is random.":"המספר ההתחלתי של הצד הזה. מוצג כ־0; המספר האמיתי אקראי.","Real sequence number":"מספר רצף אמיתי",Acknowledgment:"מספר אישור","0 (not used yet)":"0 (עדיין לא בשימוש)","A first SYN has nothing to acknowledge.":"ל־SYN הראשון אין מה לאשר.","Header length":"אורך כותרת","20 bytes, plus 12 of options.":"20 בתים, ועוד 12 של אפשרויות.",Window:"חלון","How much more data this side can take right now.":"כמה נתונים נוספים הצד הזה יכול לקבל עכשיו.","Covers the header, the data and the IP addresses, so damage is caught.":"מכסה את הכותרת, הנתונים וכתובות ה־IP, כך שנזק מתגלה.","Urgent pointer":"מצביע דחיפות",Options:"אפשרויות","Maximum segment size":"גודל מקטע מרבי","The most data this side wants in one segment.":"הכמות המרבית של נתונים שהצד הזה רוצה במקטע אחד.","Spacing, so the next option lines up.":"ריווח, כדי שהאפשרות הבאה תתחיל במקום הנכון.","Window scale":"קנה מידה לחלון","Window values are multiplied by this, so windows can be larger than 64 KB.":"ערכי החלון מוכפלים בזה, כך שחלונות יכולים להיות גדולים מ־64 KB.","SACK permitted":"SACK מותר",yes:"כן","This side understands selective acknowledgements.":"הצד הזה מבין אישורים סלקטיביים.","Started at 64; 12 routers on the way each took 1.":"התחיל ב־64; כל אחד מ־12 הנתבים בדרך הוריד 1.","The next byte this side expects: everything before it has arrived.":"הבית הבא שהצד הזה מצפה לו: כל מה שלפניו הגיע.","Position of this segment’s first byte, counted from this side’s SYN.":"מיקום הבית הראשון של המקטע הזה, נספר מה־SYN של הצד הזה.",Padding:"ריפוד","Ethernet frames are at least 60 bytes (64 with the checksum the card adds), so short ones are padded.":"מסגרות Ethernet הן לפחות 60 בתים (64 עם סכום הביקורת שהכרטיס מוסיף), ולכן מסגרות קצרות מרופדות.",Text:"טקסט","covers bytes not shown here":"כולל בתים שלא מוצגים כאן","12,500 bytes: the HTML page":"12,500 בתים: דף ה־HTML","The page itself; its contents are not part of the lesson.":"הדף עצמו; התוכן שלו אינו חלק מהשיעור.","Secure Web":"ווב מאובטח","TLS handshake":"לחיצת יד TLS","HTTP request":"בקשת HTTP","HTTP response":"תגובת HTTP","HTTPS is HTTP sent through an encrypted TLS connection. TLS proves the server is who it claims to be with a certificate, agrees on fresh encryption keys, and then protects every request and response from being read or changed on the way.":"HTTPS הוא HTTP שנשלח דרך חיבור TLS מוצפן. TLS מוכיח בעזרת תעודה שהשרת הוא מי שהוא טוען שהוא, מסכם על מפתחות הצפנה חדשים, ואז מגן על כל בקשה ותגובה מפני קריאה או שינוי בדרך.","Application (HTTP over TLS)":"יישום (HTTP מעל TLS)",Security:"אבטחה","TLS 1.3 (1.2 still common)":"TLS 1.3 (1.2 עדיין נפוץ)",Proves:"מוכיח","Server identity (certificate)":"זהות השרת (תעודה)","Secure page delivered":"הדף המאובטח נמסר","Encrypted, except the lookup":"מוצפן, חוץ מהחיפוש","The browser looked up the address in plain DNS, opened a TCP connection, checked the server’s certificate and agreed on keys in one round trip. Every HTTP byte after that travelled encrypted. Press REPLAY to watch it again.":"הדפדפן חיפש את הכתובת ב־DNS לא מוצפן, פתח חיבור TCP, בדק את תעודת השרת וסיכם על מפתחות בסבב אחד הלוך ושוב. כל בית של HTTP אחרי זה עבר מוצפן. לחצו על ״שוב״ כדי לצפות שוב.",Cipher:"צופן","Still visible":"עדיין גלוי","IPs, server name, sizes":"כתובות IP, שם השרת, גדלים","Secure Request":"בקשה מאובטחת","Browser asks for https://":"הדפדפן מבקש https://","You type https://www.example.com. The “s” tells the browser to protect the connection with TLS, on port 443 by default. Before it can connect at all, it still has to find the server’s IP address.":"אתם מקלידים https://www.example.com. ה־״s״ אומרת לדפדפן להגן על החיבור באמצעות TLS, כברירת מחדל בפורט 443. לפני שהוא יכול להתחבר בכלל, הוא עדיין צריך למצוא את כתובת ה־IP של השרת.",Port:"פורט","DNS Lookup":"חיפוש DNS","Same lookup as HTTP, not encrypted":"אותו חיפוש כמו ב־HTTP, לא מוצפן","The lookup is exactly the same as for plain HTTP: a query to 8.8.8.8 over UDP port 53. It is not encrypted, so anyone on the path can see which name you asked for, unless the browser uses DNS over HTTPS.":"החיפוש זהה בדיוק לזה של HTTP רגיל: שאילתה ל־8.8.8.8 ב־UDP לפורט 53. הוא לא מוצפן, ולכן כל מי שבדרך יכול לראות על איזה שם שאלתם, אלא אם הדפדפן משתמש ב־DNS over HTTPS.",Encrypted:"מוצפן","No (plain DNS)":"לא (DNS רגיל)","TCP Handshake":"לחיצת יד TCP","Opens a connection to port 443":"פותח חיבור לפורט 443","TLS rides on TCP, so the same three-way handshake comes first, this time to port 443. Nothing is encrypted yet.":"TLS נוסע על גבי TCP, ולכן קודם מגיעה אותה לחיצת יד משולשת, הפעם לפורט 443. שום דבר עוד לא מוצפן.","TLS Handshake":"לחיצת יד TLS","Agrees on keys, checks the certificate":"מסכם על מפתחות, בודק את התעודה","The browser offers ciphers and key shares, including a post-quantum hybrid. The server picks it and sends its own share, then its certificate, already encrypted. The browser checks it against authorities it trusts.":"הדפדפן מציע צפנים ושיתופי מפתח, כולל שיטה היברידית פוסט־קוונטית. השרת בוחר בה ושולח את השיתוף שלו, ואחריו את התעודה שלו, כבר מוצפנת. הדפדפן בודק אותה מול רשויות שהוא סומך עליהן.",Version:"גרסה","Key exchange":"החלפת מפתחות","X25519MLKEM768 (hybrid)":"X25519MLKEM768 (היברידי)","Server name":"שם השרת","Sent in clear (SNI)":"נשלח גלוי (SNI)","key shares: hybrid + x25519":"שיתופי מפתח: היברידי + x25519","cipher: AES_128_GCM_SHA256":"צופן: AES_128_GCM_SHA256","then encrypted: cert, Finished":"אחר כך מוצפן: תעודה, Finished","handshake complete (encrypted)":"לחיצת היד הושלמה (מוצפן)","Encrypted Exchange":"חילופים מוצפנים","HTTP inside TLS records":"HTTP בתוך רשומות TLS","The GET and 200 OK are the same HTTP messages as before, sealed in TLS records that look like random “application data” on the wire. The server also hands over two session tickets, so a later visit can skip part of the handshake.":"ה־GET וה־200 OK הם אותן הודעות HTTP כמו קודם, חתומות בתוך רשומות TLS שנראות על הקו כמו ״נתוני יישום״ אקראיים. השרת גם מוסר שני כרטיסי סשן, כדי שביקור מאוחר יותר יוכל לדלג על חלק מלחיצת היד.",Inside:"בפנים","GET / and 200 OK":"GET / ו־200 OK",Tickets:"כרטיסים","2, for faster reconnects":"2, לחיבור מחדש מהיר יותר","inside: GET / HTTP/1.1":"בפנים: GET / HTTP/1.1","outside: encrypted bytes":"בחוץ: בתים מוצפנים","inside: HTTP/1.1 200 OK":"בפנים: HTTP/1.1 200 OK","outside: 12.9 KB, 9 segments":"בחוץ: 12.9 KB, 9 מקטעים","Browser shows the padlock":"הדפדפן מציג את המנעול","The browser decrypts the response, paints the page and shows a padlock: the connection is private and the server proved its identity. The Strict-Transport-Security header tells it to use HTTPS for this site from now on.":"הדפדפן מפענח את התגובה, מצייר את הדף ומציג מנעול: החיבור פרטי והשרת הוכיח את זהותו. הכותרת Strict-Transport-Security אומרת לו להשתמש מעכשיו ב־HTTPS לאתר הזה.",Remembers:"זוכר","HTTPS only (HSTS), 1 year":"רק HTTPS (HSTS), שנה אחת","Server Hello + encrypted handshake, 3 segments":"Server Hello + לחיצת יד מוצפנת, 3 מקטעים","Change Cipher Spec, Finished (encrypted)":"Change Cipher Spec, Finished (מוצפן)","Application Data (HTTP request)":"Application Data (בקשת HTTP)","New Session Ticket ×2 (encrypted)":"New Session Ticket ×2 (מוצפן)","Application Data (HTTP response), 9 segments":"Application Data (תגובת HTTP), 9 מקטעים",Record:"רשומה","Content type":"סוג תוכן","A Client Hello’s record says TLS 1.0 so old middleboxes let it through; the real versions are offered inside.":"הרשומה של Client Hello מציינת TLS 1.0 כדי שהתקני ביניים ישנים יעבירו אותה; הגרסאות האמיתיות מוצעות בפנים.","Handshake type":"סוג לחיצת יד",Contents:"תוכן","Everything the browser supports. Browsers vary a few details from one connection to the next.":"כל מה שהדפדפן תומך בו. דפדפנים משנים כמה פרטים מחיבור לחיבור.","Server name (SNI)":"שם השרת (SNI)","Versions offered":"גרסאות מוצעות","Key shares":"שיתופי מפתח","App protocols (ALPN)":"פרוטוקולי יישום (ALPN)","TLS 1.3 records say 1.2 on the outside, for compatibility.":"רשומות TLS 1.3 מציינות 1.2 מבחוץ, לשם תאימות.","The server’s choices and its half of the hybrid key exchange.":"הבחירות של השרת והחצי שלו בהחלפת המפתחות ההיברידית.","Cipher suite":"חבילת הצפנה","Key share":"שיתוף מפתח","Has no job in TLS 1.3; sent so middleboxes see a familiar handshake.":"אין לו תפקיד ב־TLS 1.3; נשלח כדי שהתקני ביניים יראו לחיצת יד מוכרת.","Every encrypted record says Application Data on the outside; the real type is inside.":"כל רשומה מוצפנת מציינת Application Data מבחוץ; הסוג האמיתי נמצא בפנים.","Encrypted data":"נתונים מוצפנים","Ciphertext, ending in a 16-byte tag that shows any change. Only the two ends can read it.":"טקסט מוצפן, שמסתיים בתג של 16 בתים שחושף כל שינוי. רק שני הקצוות יכולים לקרוא אותו.","Encrypted Extensions (ALPN: http/1.1), Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions (ALPN: http/1.1), Certificate (השרשרת), Certificate Verify (החתימה), Finished","Finished: a check value over the whole handshake":"Finished: ערך ביקורת על כל לחיצת היד","The HTTP request":"בקשת ה־HTTP","New Session Ticket: lets a later visit resume":"New Session Ticket: מאפשר לביקור מאוחר יותר לחדש את הסשן","The HTTP response, then the 12,500-byte page":"תגובת ה־HTTP, ואחריה הדף בן 12,500 הבתים","Reliable Delivery":"מסירה אמינה","Handshake and ACKs":"לחיצת יד ואישורי ACK","Data from laptop":"נתונים מהמחשב הנייד","Data from server":"נתונים מהשרת","Closing (FIN)":"סגירה (FIN)","TCP turns the internet’s best-effort packet delivery into a reliable, ordered stream of bytes. It numbers every byte, acknowledges what arrives, resends what goes missing, and paces the sender so neither the other side nor the network is overwhelmed.":"TCP הופך את מסירת החבילות ״במאמץ הטוב ביותר״ של האינטרנט לזרם בתים אמין ומסודר. הוא ממספר כל בית, מאשר את מה שמגיע, שולח מחדש את מה שאובד, ומווסת את קצב השולח כדי לא להציף את הצד השני או את הרשת.","Transport (Layer 4)":"תעבורה (שכבה 4)","Three-way handshake":"לחיצת יד משולשת",Reliability:"אמינות","Sequence numbers + ACKs":"מספרי רצף + ACK",Recovery:"התאוששות",Retransmission:"שידור חוזר",Header:"כותרת","Connection closed":"החיבור נסגר","Every byte accounted for":"כל בית נספר","TCP opened a connection, numbered and acknowledged every byte, spotted a gap and resent just the missing segment, then closed both directions cleanly. curl received every byte in order and never saw the loss. Press REPLAY to watch it again.":"TCP פתח חיבור, מספר ואישר כל בית, זיהה פער ושלח מחדש רק את המקטע החסר, ואז סגר את שני הכיוונים בצורה מסודרת. curl קיבל כל בית לפי הסדר ולא הרגיש באובדן. לחצו על ״שוב״ כדי לצפות שוב.",Segments:"מקטעים","14 (1 lost, 1 resent)":"14 (1 אבד, 1 נשלח מחדש)","Bytes delivered":"בתים שנמסרו","78 up, 2,920 down":"78 בהעלאה, 2,920 בהורדה","Loss found by":"האובדן התגלה באמצעות","Duplicate ACK + SACK":"ACK כפול + SACK","Open Connection":"פתיחת חיבור","curl already knows the server’s address. Before any data moves, both sides choose a starting sequence number and confirm it: SYN, SYN-ACK, ACK. The numbers here are relative; real ones start at a random value.":"curl כבר יודע את כתובת השרת. לפני שנתונים כלשהם זזים, כל צד בוחר מספר רצף התחלתי ומאשר אותו: SYN, SYN-ACK, ACK. המספרים כאן יחסיים; האמיתיים מתחילים בערך אקראי.",Server:"שרת","203.0.113.10, port 80":"203.0.113.10, פורט 80","Send Data":"שליחת נתונים","Every byte is numbered":"כל בית ממוספר","curl sends its 78-byte HTTP request: bytes 1 to 78. The server’s ACK number, 79, is the next byte it expects, which means everything before it has arrived.":"curl שולח את בקשת ה־HTTP שלו בת 78 הבתים: בתים 1 עד 78. מספר ה־ACK של השרת, 79, הוא הבית הבא שהוא מצפה לו, כלומר כל מה שלפניו הגיע.",Sent:"נשלח","79 = next byte expected":"79 = הבית הבא הצפוי","Two Segments Back":"שני מקטעים בחזרה","One of them is lost":"אחד מהם אובד","The server answers with 2,920 bytes: two full segments of 1,460 bytes, the most that fits in one packet here, sent back to back. The first is dropped somewhere on the internet; the second gets through.":"השרת עונה ב־2,920 בתים: שני מקטעים מלאים של 1,460 בתים, המקסימום שנכנס כאן בחבילה אחת, שנשלחים זה אחר זה. הראשון נופל איפשהו באינטרנט; השני עובר.","Segment 1":"מקטע 1","bytes 1–1460 (lost)":"בתים 1–1460 (אבד)","Segment 2":"מקטע 2","Segment size":"גודל מקטע","seq=1 and seq=1461":"seq=1 ו־seq=1461","the first is lost":"הראשון אובד","A Gap Is Noticed":"מתגלה פער","Duplicate ACK with SACK":"ACK כפול עם SACK","Bytes 1461–2920 arrive, but 1–1460 never did. An ACK can only count bytes received in order, so the laptop repeats ACK 1 at once and adds a SACK block saying it already holds 1461–2920.":"בתים 1461–2920 מגיעים, אבל 1–1460 לא הגיעו מעולם. ACK יכול לספור רק בתים שהתקבלו לפי הסדר, ולכן המחשב הנייד חוזר מיד על ACK 1 ומוסיף בלוק SACK שאומר שבתים 1461–2920 כבר אצלו.","1 (still waiting for byte 1)":"1 (עדיין מחכה לבית 1)","holds bytes 1461–2920":"בתים 1461–2920 אצלו","At once, not delayed":"מיד, בלי השהיה","sack: has 1461–2920":"sack: יש 1461–2920","Resend the Gap":"שליחת הפער מחדש","Only the missing bytes":"רק הבתים החסרים","The SACK tells the server exactly what is missing, so it resends just segment 1, and the laptop acknowledges everything. Had no ACK come back at all, timers would have stepped in: a probe after about two round trips, then a retransmission timeout (at least 200 ms on Linux).":"ה־SACK אומר לשרת בדיוק מה חסר, ולכן הוא שולח מחדש רק את מקטע 1, והמחשב הנייד מאשר הכול. אילו לא היה חוזר שום ACK, טיימרים היו נכנסים לפעולה: קודם חבילת בדיקה אחרי כשני סבבים הלוך ושוב, ואחר כך פסק הזמן לשידור חוזר (לפחות 200 ms ב־Linux).",Resent:"נשלח מחדש","bytes 1–1460 only":"רק בתים 1–1460","Next ACK":"ה־ACK הבא","2921 (everything)":"2921 (הכול)","curl saw":"curl ראה","Every byte, in order":"כל בית, לפי הסדר","just the missing segment":"רק המקטע החסר","Close Connection":"סגירת חיבור","Each side says goodbye":"כל צד נפרד","curl is done, so it closes. Each direction closes on its own: the laptop sends FIN and the server acknowledges it, then the server sends its own FIN and the laptop acknowledges that. The laptop keeps the connection’s details for a while (TIME-WAIT).":"curl סיים, ולכן הוא סוגר. כל כיוון נסגר בנפרד: המחשב הנייד שולח FIN והשרת מאשר אותו, ואז השרת שולח FIN משלו והמחשב הנייד מאשר אותו. המחשב הנייד שומר את פרטי החיבור לזמן מה (TIME-WAIT).","Closed by":"נסגר על ידי","A FIN from each side":"FIN מכל צד",Order:"סדר",Then:"ואז","Laptop waits (TIME-WAIT)":"המחשב הנייד ממתין (TIME-WAIT)",Data:"נתונים","1,460 bytes: the HTTP response, bytes 1–1460":"1,460 בתים: תגובת ה־HTTP, בתים 1–1460","1,460 bytes: the HTTP response, bytes 1461–2920":"1,460 בתים: תגובת ה־HTTP, בתים 1461–2920","has 1461–2920":"יש 1461–2920","Bytes that arrived after the gap, so only the gap needs resending.":"בתים שהגיעו אחרי הפער, כך שרק את הפער צריך לשלוח מחדש.","Fast Datagrams":"דאטגרמות מהירות","Your voice":"הקול שלכם","Their voice":"הקול של הצד השני","Media Server":"שרת מדיה","UDP sends data in independent packets called datagrams, with no connection, no acknowledgements and no resends. That keeps it fast and light: right for voice, video, games and DNS, where a late answer is worse than a missing one.":"UDP שולח נתונים בחבילות עצמאיות שנקראות דאטגרמות, בלי חיבור, בלי אישורים ובלי שליחות חוזרות. זה שומר עליו מהיר וקל: מתאים לקול, וידאו, משחקים ו־DNS, שבהם תשובה מאוחרת גרועה יותר מתשובה חסרה.",None:"אין","None (no ACKs, no resends)":"אין (בלי ACK, בלי שליחה חוזרת)",Ordering:"סדר","Not guaranteed":"לא מובטח","Call keeps flowing":"השיחה ממשיכה לזרום","Fast, simple, no guarantees":"מהיר, פשוט, בלי התחייבויות","Audio started with the very first packet, every datagram travelled on its own, and the one that was lost was simply gone: UDP never noticed. The app covered the gap and the call carried on. Press REPLAY to watch it again.":"האודיו התחיל כבר עם החבילה הראשונה, כל דאטגרמה נסעה בעצמה, וזו שאבדה פשוט נעלמה: UDP לא שם לב בכלל. האפליקציה כיסתה את הפער והשיחה נמשכה. לחצו על ״שוב״ כדי לצפות שוב.",Datagrams:"דאטגרמות","11 (1 lost, never resent)":"11 (1 אבדה, לא נשלחה מחדש)","Setup time":"זמן הקמה","0 ms (no handshake)":"0 ms (בלי לחיצת יד)",Shown:"מוצג","The first 0.2 s of a call":"0.2 s הראשונות של שיחה","Send Right Away":"שליחה מיידית","No handshake, data goes first":"בלי לחיצת יד, הנתונים יוצאים ראשונים","A call app already knows the media server’s address and port from signing in. It doesn’t open a connection: the very first datagram already carries 20 ms of your voice, behind an 8-byte UDP header.":"אפליקציית שיחות כבר יודעת את הכתובת והפורט של שרת המדיה מההתחברות. היא לא פותחת חיבור: הדאטגרמה הראשונה כבר נושאת 20 ms מהקול שלכם, מאחורי כותרת UDP של 8 בתים.",Setup:"הקמה",Ports:"פורטים","92 B of audio, no setup":"92 B של אודיו, בלי הקמה","A Stream of Datagrams":"זרם של דאטגרמות","One every 20 ms, each on its own":"אחת כל 20 ms, כל אחת לעצמה","The app keeps sending a datagram every 20 ms. Each one stands alone, with its own header and no link to the others. UDP doesn’t number them, and nothing comes back to confirm they arrived.":"האפליקציה ממשיכה לשלוח דאטגרמה כל 20 ms. כל אחת עומדת בפני עצמה, עם כותרת משלה ובלי קשר לאחרות. UDP לא ממספר אותן, ושום דבר לא חוזר כדי לאשר שהן הגיעו.",Rate:"קצב","1 datagram / 20 ms":"1 דאטגרמה / 20 ms",Numbering:"מספור","None in UDP itself":"אין ב־UDP עצמו",Confirmation:"אישור","None (no ACKs)":"אין (בלי ACK)","voice frames 2–5":"מסגרות קול 2–5","each with its own 8-byte header":"כל אחת עם כותרת משלה של 8 בתים","Lost on the Way":"אבדה בדרך","Nobody resends it":"אף אחד לא שולח אותה מחדש","Frame 7 is dropped somewhere on the internet. The media server never asks for it, and UDP never tells the laptop: there are no acknowledgements to miss. The datagrams after it arrive as normal.":"מסגרת 7 נופלת איפשהו באינטרנט. שרת המדיה אף פעם לא מבקש אותה, ו־UDP אף פעם לא מודיע למחשב הנייד: אין אישורים שיכולים להיעדר. הדאטגרמות שאחריה מגיעות כרגיל.",Lost:"אבדה","Voice frame 7":"מסגרת קול 7","Never (no ACKs)":"אף פעם (בלי ACK)",Missing:"חסר","20 ms of audio":"20 ms של אודיו","voice frames 6–8":"מסגרות קול 6–8","frame 7 is lost":"מסגרת 7 אובדת","Replies Come Back":"תשובות חוזרות","The other voice comes back":"הקול השני חוזר","The other person’s voice arrives the same way, as separate datagrams sent to port 50000. They get back in because your router remembered the outgoing port when it translated your address (NAT).":"הקול של הצד השני מגיע באותה דרך, כדאטגרמות נפרדות שנשלחות לפורט 50000. הן נכנסות כי הנתב שלכם זכר את הפורט היוצא כשתרגם את הכתובת שלכם (NAT).",Direction:"כיוון","Independent of ours":"בלתי תלוי בשלנו","Through NAT":"דרך NAT","Router remembers the port":"הנתב זוכר את הפורט","the other person’s voice":"הקול של הצד השני","sent to port 50000":"נשלח לפורט 50000","The App Decides":"האפליקציה מחליטה","Reliability is up to the app":"האמינות באחריות האפליקציה","The call app numbers its own frames (RTP does this), so it sees that frame 7 is missing and smooths over the 20 ms gap instead of waiting. Waiting for a resend would make the whole call lag.":"אפליקציית השיחות ממספרת את המסגרות שלה בעצמה (RTP עושה את זה), ולכן היא רואה שמסגרת 7 חסרה ומחליקה את הפער של 20 ms במקום לחכות. המתנה לשליחה חוזרת הייתה גורמת לכל השיחה לפגר.","App’s job (e.g. RTP)":"תפקיד האפליקציה (למשל RTP)",Loss:"אובדן","Hidden by the app":"מוסתר על ידי האפליקציה","Also on UDP":"גם על UDP","DNS, games, QUIC":"DNS, משחקים, QUIC","Version etc.":"גרסה וכו׳","2, no padding, no extension, no CSRCs":"2, בלי ריפוד, בלי הרחבה, בלי CSRC","Marker, payload type":"סמן, סוג מטען","1, 111 (Opus, agreed when the call was set up)":"1, 111 (Opus, סוכם בהקמת השיחה)","Counts up by one per packet, so the app can spot a missing or late one.":"עולה באחד בכל חבילה, כדי שהאפליקציה תזהה חבילה חסרה או מאוחרת.",Timestamp:"חותמת זמן","Audio clock at 48,000 per second: +960 per 20 ms frame.":"שעון אודיו של 48,000 בשנייה: +960 לכל מסגרת של 20 ms.","Identifies this audio stream.":"מזהה את זרם האודיו הזה.",Audio:"אודיו","80 bytes of Opus audio (20 ms)":"80 בתים של אודיו Opus (20 ms)","0, 111 (Opus, agreed when the call was set up)":"0, 111 (Opus, סוכם בהקמת השיחה)","Addressing & Routing":"מיעון וניתוב","Outgoing packet":"חבילה יוצאת",Reply:"תשובה","IP gives every device an address and moves packets from network to network. Each router looks only at the destination address to choose the next hop. IP is best effort: it doesn’t promise delivery or order. TCP adds those on top.":"IP נותן לכל מכשיר כתובת ומעביר חבילות מרשת לרשת. כל נתב מסתכל רק על כתובת היעד כדי לבחור את הקפיצה הבאה. IP פועל ״במאמץ הטוב ביותר״: הוא לא מבטיח מסירה או סדר. TCP מוסיף אותם מעליו.","Network (Layer 3)":"רשת (שכבה 3)",Address:"כתובת","Lowered by 1 at each router":"יורד ב־1 בכל נתב",Delivery:"מסירה","Best effort":"במאמץ הטוב ביותר","There and back":"הלוך ושוב","Twelve routers each way":"שנים־עשר נתבים לכל כיוון","The laptop sent the packet to its router, which swapped in its public address. Twelve routers in all passed it along by destination address alone, and the reply found its way back the same way. Press REPLAY to watch it again.":"המחשב הנייד שלח את החבילה לנתב שלו, שהכניס בה את הכתובת הציבורית שלו. בסך הכול שנים־עשר נתבים העבירו אותה הלאה לפי כתובת היעד בלבד, והתשובה מצאה את דרכה חזרה באותה צורה. לחצו על ״שוב״ כדי לצפות שוב.",Routers:"נתבים","12 each way (1 home + 11)":"12 לכל כיוון (1 ביתי + 11)","TTL at server":"TTL בשרת","116 (sent with 128)":"116 (נשלח עם 128)","Rewritten by NAT":"משוכתב על ידי NAT","Source out, destination back":"המקור ביציאה, היעד בחזרה","IPv4 (IPv6 works alike)":"IPv4 (גם IPv6 עובד כך)","Local or Not?":"מקומי או לא?","Compare the address with the subnet":"משווים את הכתובת לתת־הרשת","The laptop is 192.168.1.10 with a /24 mask, so its own network is 192.168.1.0 to 192.168.1.255. The server, 203.0.113.10, is outside that range, so the packet has to go to the default gateway: the home router.":"למחשב הנייד יש כתובת 192.168.1.10 עם מסכה /24, ולכן הרשת שלו היא 192.168.1.0 עד 192.168.1.255. השרת, 203.0.113.10, מחוץ לטווח הזה, ולכן החבילה חייבת ללכת לשער ברירת המחדל: הנתב הביתי.",Laptop:"מחשב נייד","Local range":"טווח מקומי",Gateway:"שער","Find the Router":"מציאת הנתב","ARP turns an IP into a MAC":"ARP הופך IP ל־MAC","On the local network, frames are delivered by MAC address. If the router’s MAC isn’t in the laptop’s ARP cache, it broadcasts “who has 192.168.1.1?” and the router answers with its MAC address.":"ברשת המקומית, מסגרות נמסרות לפי כתובת MAC. אם כתובת ה־MAC של הנתב לא נמצאת במטמון ה־ARP של המחשב הנייד, הוא משדר לכולם ״למי יש 192.168.1.1?״ והנתב עונה עם כתובת ה־MAC שלו.",Asks:"שואל","Who has 192.168.1.1?":"למי יש 192.168.1.1?","Sent to":"נשלח אל","Everyone (broadcast)":"כולם (שידור)",Learns:"לומד","Router’s MAC address":"כתובת ה־MAC של הנתב","who has 192.168.1.1?":"למי יש 192.168.1.1?","tell 192.168.1.10":"תודיע ל־192.168.1.10","Send the Packet":"שליחת החבילה","Addresses, TTL and protocol":"כתובות, TTL ופרוטוקול","The IP header carries the source and destination addresses, a TTL and the protocol inside. Here it holds a TCP SYN to port 443. Windows starts the TTL at 128 (Linux and macOS use 64).":"כותרת ה־IP נושאת את כתובות המקור והיעד, ערך TTL ואת הפרוטוקול שבפנים. כאן היא מכילה TCP SYN לפורט 443. Windows מתחיל את ה־TTL ב־128 (Linux ו־macOS משתמשים ב־64).","From → to":"מאיפה ← לאן","TTL 128 · protocol TCP":"TTL 128 · פרוטוקול TCP","NAT, Then Hop by Hop":"NAT, ואז קפיצה אחר קפיצה","The router rewrites and forwards":"הנתב משכתב ומעביר הלאה","The router swaps the private source for its public address 198.51.100.7 (and here port 52344 for 40112), notes the mapping, and lowers the TTL to 127. Then 11 routers on the internet each choose the next hop by destination and lower the TTL again.":"הנתב מחליף את המקור הפרטי בכתובת הציבורית שלו 198.51.100.7 (וכאן את פורט 52344 ב־40112), רושם את המיפוי, ומוריד את ה־TTL ל־127. אחר כך 11 נתבים באינטרנט בוחרים כל אחד את הקפיצה הבאה לפי היעד ומורידים שוב את ה־TTL.","New source":"מקור חדש","Leaves home":"ביציאה מהבית","At the server":"בשרת","TTL 116 (11 more hops)":"TTL 116 (עוד 11 קפיצות)","TTL 127 · after NAT":"TTL 127 · אחרי NAT","The Reply Comes Back":"התשובה חוזרת","NAT translates it for the laptop":"NAT מתרגם אותה עבור המחשב הנייד","The server answers the address it saw, 198.51.100.7:40112. The router looks that up in its NAT table, rewrites the destination back to 192.168.1.10:52344 and passes it on. The reply started at TTL 64 and arrives with 52.":"השרת עונה לכתובת שהוא ראה, 198.51.100.7:40112. הנתב מחפש אותה בטבלת ה־NAT שלו, משכתב את היעד בחזרה ל־192.168.1.10:52344 ומעביר אותה הלאה. התשובה התחילה עם TTL 64 ומגיעה עם 52.","Delivered to":"נמסר אל","TTL 52 · after NAT":"TTL 52 · אחרי NAT","TTL 127 · 40112 → 443 [SYN] (after NAT)":"TTL 127 · 40112 → 443 [SYN] (אחרי NAT)","TTL 52 · 443 → 52344 [SYN, ACK] (after NAT)":"TTL 52 · 443 → 52344 [SYN, ACK] (אחרי NAT)","ARP request · 28 bytes":"בקשת ARP · 28 בתים","Broadcast: every device on the network receives it.":"שידור לכולם: כל מכשיר ברשת מקבל אותה.","The sender’s network card.":"כרטיס הרשת של השולח.","Hardware type":"סוג חומרה","Protocol type":"סוג פרוטוקול","Address sizes":"גודלי כתובות",Operation:"פעולה","1 (request: who has …?)":"1 (בקשה: למי יש …?)","Sender MAC":"MAC של השולח","Sender IP":"IP של השולח","Target MAC":"MAC של היעד","All zeros: this is what the request wants to find out.":"כולו אפסים: זה מה שהבקשה רוצה לגלות.","Target IP":"IP של היעד","ARP reply · 28 bytes":"תשובת ARP · 28 בתים","Straight back to the device that asked.":"ישירות בחזרה למכשיר ששאל.","2 (reply: … is at …)":"2 (תשובה: … נמצא ב־…)","Seen as it leaves the router’s internet side":"כפי שנראתה ביציאה מהצד של הנתב הפונה לאינטרנט","The internet provider’s router, the next hop.":"הנתב של ספק האינטרנט, הקפיצה הבאה.","The router’s internet-facing port.":"הפורט של הנתב הפונה לאינטרנט.","As sent: this system starts at 64.":"כפי שנשלח: המערכת הזו מתחילה ב־64.","The router’s NAT swapped in its own port for the laptop’s.":"ה־NAT של הנתב החליף את הפורט של המחשב הנייד בפורט משלו.","The sender’s next router; each hop puts the packet in a new frame.":"הנתב הבא של השולח; כל קפיצה מכניסה את החבילה למסגרת חדשה.","Name Resolution":"פענוח שמות",Query:"שאילתה",Referral:"הפניה","DNSSEC not requested here":"DNSSEC לא התבקש כאן","DNS turns names like www.example.com into the IP addresses computers use to reach each other. No single server knows every name: the system is a hierarchy of servers, and answers are cached along the way so most lookups never have to go far.":"DNS הופך שמות כמו www.example.com לכתובות IP שמחשבים משתמשים בהן כדי להגיע זה לזה. אין שרת אחד שמכיר כל שם: המערכת היא היררכיה של שרתים, ותשובות נשמרות במטמון לאורך הדרך, כך שרוב החיפושים לא צריכים להגיע רחוק.","53, UDP (TCP if large)":"53, UDP (או TCP אם גדול)",Turns:"הופך","Names into IP addresses":"שמות לכתובות IP",Hierarchy:"היררכיה","Root → TLD → authoritative":"שורש ← TLD ← מוסמך",Caching:"מטמון","For each record’s TTL":"לפי ה־TTL של כל רשומה","Name resolved":"השם פוענח","And remembered for an hour":"ונשמר לשעה","Starting from an empty cache, the resolver walked from the root to .com to example.com’s own server, then answered the laptop. Until the TTL runs out, the next lookup for this name is answered straight from a cache. Press REPLAY to watch it again.":"החל ממטמון ריק, הרזולבר עבר מהשורש ל־.com ולשרת של example.com עצמו, ואז ענה למחשב הנייד. עד שה־TTL יפוג, החיפוש הבא של השם הזה ייענה ישר מהמטמון. לחצו על ״שוב״ כדי לצפות שוב.",Queries:"שאילתות","4 (laptop 1, resolver 3)":"4 (המחשב הנייד 1, הרזולבר 3)","Cached for":"נשמר במטמון למשך","Ask the Resolver":"שואלים את הרזולבר","The laptop hands the question off":"המחשב הנייד מעביר את השאלה","The browser needs the IP address of www.example.com and neither it nor Windows has one cached. The laptop sends one question to the recursive resolver it was given, 8.8.8.8, and asks it to do the whole lookup (recursion desired).":"הדפדפן צריך את כתובת ה־IP של www.example.com, ולא לו ולא ל־Windows יש אותה במטמון. המחשב הנייד שולח שאלה אחת לרזולבר הרקורסיבי שהוגדר לו, 8.8.8.8, ומבקש ממנו לבצע את כל החיפוש (רקורסיה רצויה).","www.example.com, type A":"www.example.com, סוג A",Asked:"נשאל","8.8.8.8 (recursive)":"8.8.8.8 (רקורסיבי)","RD (recursion desired)":"RD (רקורסיה רצויה)","flags: RD":"דגלים: RD","Points the way to .com":"מכוון אל .com","The resolver’s cache is empty (it has just started), so it begins at the top. A root server doesn’t know the address, but it knows which servers handle .com and replies with a referral. Many resolvers send it only “com”, not the full name.":"המטמון של הרזולבר ריק (הוא רק התחיל), ולכן הוא מתחיל מלמעלה. שרת שורש לא יודע את הכתובת, אבל הוא יודע אילו שרתים מטפלים ב־.com ועונה בהפניה. רזולברים רבים שולחים לו רק ״com״, לא את השם המלא.","Root servers":"שרתי שורש","13 names, 1,000+ anycast sites":"13 שמות, יותר מ־1,000 אתרי anycast","Referral (13 .com servers)":"הפניה (13 שרתי .com)","no answer: ask .com":"אין תשובה: לשאול את .com","Points the way to example.com":"מכוון אל example.com","The resolver asks one of the .com servers. They don’t store addresses for every site either, but they know which name servers each .com domain uses, so this reply is another referral, with those servers’ addresses (glue) attached.":"הרזולבר שואל אחד משרתי ה־.com. גם הם לא שומרים כתובות לכל אתר, אבל הם יודעים באילו שרתי שמות משתמש כל דומיין .com, ולכן גם התשובה הזו היא הפניה, עם הכתובות של אותם שרתים (glue) מצורפות.",Knows:"יודע","Name servers of .com domains":"שרתי השמות של דומיינים ב־.com","Referral + glue addresses":"הפניה + כתובות glue","no answer: ask example.com":"אין תשובה: לשאול את example.com","Gives the actual answer":"נותן את התשובה עצמה","Finally the resolver asks example.com’s own name server, which holds the domain’s records. It answers with the A record and marks the reply authoritative. The domain owner sets how long it may be cached: here, 3600 seconds.":"לבסוף הרזולבר שואל את שרת השמות של example.com עצמו, שמחזיק את הרשומות של הדומיין. הוא עונה עם רשומת A ומסמן את התשובה כמוסמכת. בעל הדומיין קובע כמה זמן מותר לשמור אותה במטמון: כאן, 3600 שניות.","AA (authoritative), TTL 3600":"AA (מוסמך), TTL 3600","TTL 3600 · flag AA":"TTL 3600 · דגל AA","Answer & Cache":"תשובה ומטמון","The laptop gets its address":"המחשב הנייד מקבל את הכתובת שלו","The resolver sends the answer back to the laptop and keeps a copy. For the next hour it can answer this name straight away, which is why the lookup in the HTTP lesson took only 24 ms. The laptop caches it too.":"הרזולבר שולח את התשובה חזרה למחשב הנייד ושומר עותק. במשך השעה הבאה הוא יכול לענות על השם הזה מיד, ולכן החיפוש בשיעור ה־HTTP לקח רק 24 ms. גם המחשב הנייד שומר אותה במטמון.","RD, RA (recursion available)":"RD, RA (רקורסיה זמינה)","Cached by":"נשמר במטמון אצל","Resolver and laptop":"הרזולבר והמחשב הנייד","flags: RD RA":"דגלים: RD RA","Referral: com. NS ×13 (with glue)":"הפניה: com. NS ×13 (עם glue)","Referral: example.com. NS ×2 (with glue)":"הפניה: example.com. NS ×2 (עם glue)","Response A 203.0.113.10 (authoritative)":"תגובה A 203.0.113.10 (מוסמכת)","As sent: this system starts at 128.":"כפי שנשלח: המערכת הזו מתחילה ב־128.","0x0000: query":"0x0000: שאילתה","UDP size 1232, DNSSEC OK = 0":"גודל UDP 1232, DNSSEC OK = 0","Says how big a UDP answer can be. DNSSEC signatures are not asked for here, to keep the lesson short; a validating resolver like 8.8.8.8 does ask for them.":"מציין כמה גדולה יכולה להיות תשובת UDP. חתימות DNSSEC לא מתבקשות כאן, כדי שהשיעור יישאר קצר; רזולבר מאמת כמו 8.8.8.8 כן מבקש אותן.","0x8000: response":"0x8000: תגובה",Authority:"סמכות",Additional:"נוספות","0x8400: response, AA (authoritative)":"0x8400: תגובה, AA (מוסמכת)","Getting an Address":"קבלת כתובת","From the laptop":"מהמחשב הנייד","From the DHCP server":"משרת ה־DHCP","Dynamic Host Configuration Protocol":"פרוטוקול הגדרת מארח דינמית","DHCP hands a device everything it needs to use a network: an IP address, the subnet mask, the router to send traffic through and the DNS servers to ask. Addresses are leased for a set time and renewed while the device stays on the network.":"DHCP נותן למכשיר כל מה שהוא צריך כדי להשתמש ברשת: כתובת IP, מסכת תת־רשת, הנתב שדרכו שולחים תעבורה ושרתי ה־DNS שאותם שואלים. כתובות מוחכרות לזמן קבוע ומחודשות כל עוד המכשיר נשאר ברשת.","UDP 67 (server), 68 (client)":"UDP 67 (שרת), 68 (לקוח)","Hands out":"מחלק","IP, mask, gateway, DNS":"IP, מסכה, שער, DNS",Exchange:"חילופים",Lease:"חכירה","Renewed at half its time":"מחודשת במחצית הזמן","On the network":"ברשת","Leased, and kept up to date":"מוחכרת, ומתעדכנת","Four messages took the laptop from no address to a working configuration, and halfway through the 24-hour lease it renewed it with a direct request to the router. Press REPLAY to watch it again.":"ארבע הודעות לקחו את המחשב הנייד ממצב בלי כתובת להגדרה עובדת, ובמחצית החכירה של 24 שעות הוא חידש אותה בבקשה ישירה לנתב. לחצו על ״שוב״ כדי לצפות שוב.",Messages:"הודעות","4 to join, 2 per renewal":"4 להצטרפות, 2 לכל חידוש","24 h, renewed at 12 h":"24 h, חידוש אחרי 12 h","No Address Yet":"עדיין אין כתובת","The laptop joins the network":"המחשב הנייד מצטרף לרשת","The laptop has just connected. It has a MAC address built in, but no IP address, no gateway and no DNS server, so it can’t talk to anything beyond its own network yet. It asks for them with DHCP.":"המחשב הנייד בדיוק התחבר. יש לו כתובת MAC מובנית, אבל אין לו כתובת IP, שער או שרת DNS, ולכן הוא עוד לא יכול לדבר עם שום דבר מעבר לרשת שלו. הוא מבקש אותם באמצעות DHCP.","IP address":"כתובת IP","None (uses 0.0.0.0)":"אין (משתמש ב־0.0.0.0)","MAC address":"כתובת MAC",Needs:"צריך",Discover:"גילוי","Shout to the whole network":"קריאה לכל הרשת","Without an address of its own, the laptop sends from 0.0.0.0 to the broadcast address 255.255.255.255, so every device on the local network receives it. Only DHCP servers answer.":"בלי כתובת משלו, המחשב הנייד שולח מ־0.0.0.0 לכתובת השידור 255.255.255.255, כך שכל מכשיר ברשת המקומית מקבל את ההודעה. רק שרתי DHCP עונים.",From:"מאת","0.0.0.0, UDP port 68":"0.0.0.0, פורט UDP 68","255.255.255.255, port 67":"255.255.255.255, פורט 67",Carries:"נושא","MAC, transaction ID":"MAC, מזהה טרנזקציה","any DHCP server out there?":"יש כאן שרת DHCP?",Offer:"הצעה","The router proposes an address":"הנתב מציע כתובת","The router’s DHCP server picks a free address and offers it with the rest of the settings. The laptop can’t use an IP address yet, so the offer goes straight to its MAC address (some clients ask for a broadcast instead).":"שרת ה־DHCP של הנתב בוחר כתובת פנויה ומציע אותה יחד עם שאר ההגדרות. המחשב הנייד עוד לא יכול להשתמש בכתובת IP, ולכן ההצעה נשלחת ישר לכתובת ה־MAC שלו (חלק מהלקוחות מבקשים שידור לכולם במקום).",Offered:"הוצע","Gateway, DNS":"שער, DNS","offer: 192.168.1.10/24":"הצעה: 192.168.1.10/24","gateway, DNS, lease 24 h":"שער, DNS, חכירה ל־24 h","Accept, out loud":"קבלה, בקול רם","The laptop asks for the offered address, naming the server it chose. It still broadcasts, so any other DHCP server that made an offer learns it wasn’t picked and can release its address.":"המחשב הנייד מבקש את הכתובת שהוצעה, ומציין את השרת שבחר. הוא עדיין משדר לכולם, כך שכל שרת DHCP אחר שהציע הצעה יודע שלא נבחר ויכול לשחרר את הכתובת שלו.",Requests:"מבקש","Chosen server":"השרת שנבחר","I’ll take 192.168.1.10":"אני לוקח את 192.168.1.10","from server 192.168.1.1":"משרת 192.168.1.1",Acknowledge:"אישור","The address is the laptop’s":"הכתובת שייכת למחשב הנייד","The server confirms, and the laptop configures its address, mask, gateway and DNS server. Many systems first check with ARP that no other device is already using the address.":"השרת מאשר, והמחשב הנייד מגדיר את הכתובת, המסכה, השער ושרת ה־DNS. מערכות רבות בודקות קודם באמצעות ARP שאף מכשיר אחר לא משתמש כבר בכתובת.","DNS server":"שרת DNS","192.168.1.10 is yours":"192.168.1.10 שלך","for 24 hours":"ל־24 שעות",Renew:"חידוש","Halfway through the lease":"באמצע החכירה","Twelve hours later, half the lease has passed. The laptop now has an address, so it asks the router directly to extend the lease, and the router resets it to 24 hours. If the router didn’t answer, it would broadcast at 87.5%.":"שתים־עשרה שעות אחר כך, חצי מהחכירה עבר. עכשיו יש למחשב הנייד כתובת, ולכן הוא מבקש מהנתב ישירות להאריך את החכירה, והנתב מאפס אותה ל־24 שעות. אם הנתב לא היה עונה, הוא היה משדר לכולם ב־87.5%.",When:"מתי","50% of lease (T1 = 12 h)":"50% מהחכירה (T1 = 12 h)","The router (unicast)":"הנתב (unicast)","If unanswered":"אם אין תשובה","Broadcast at 87.5% (T2)":"שידור לכולם ב־87.5% (T2)","renew 192.168.1.10":"חידוש 192.168.1.10","sent straight to 192.168.1.1":"נשלח ישר ל־192.168.1.1","lease renewed":"החכירה חודשה","another 24 hours":"עוד 24 שעות",Message:"הודעה","1 (request, from a client)":"1 (בקשה, מלקוח)",Hardware:"חומרה","Ethernet, 6-byte addresses":"Ethernet, כתובות של 6 בתים",Hops:"קפיצות","Chosen by the client; every reply repeats it.":"נבחר על ידי הלקוח; כל תשובה חוזרת עליו.",Seconds:"שניות","0x0000 (unicast replies are fine)":"0x0000 (תשובות unicast בסדר)","Broadcast flag off: the server may send straight to the client’s MAC address.":"דגל השידור כבוי: השרת רשאי לשלוח ישר לכתובת ה־MAC של הלקוח.","Client address":"כתובת הלקוח","Filled in only when the client already has an address (renewing).":"ממולא רק כשכבר יש ללקוח כתובת (בחידוש).","Your address":"הכתובת שלך","The address the server is giving out.":"הכתובת שהשרת מחלק.","Next server":"השרת הבא","Relay agent":"סוכן ממסר","Client MAC":"MAC של הלקוח","Server name, boot file":"שם שרת, קובץ אתחול",empty:"ריק","Magic cookie":"Magic cookie","Marks the options that follow as DHCP.":"מסמן שהאפשרויות שאחריו הן של DHCP.","Message type: 1 (Discover)":"סוג הודעה: 1 (Discover)","Client identifier: 01 00:00:5e:00:53:10":"מזהה לקוח: 01 00:00:5e:00:53:10","Host name: alice-laptop":"שם מארח: alice-laptop","Vendor class: MSFT 5.0":"מחלקת ספק: MSFT 5.0","Parameters wanted: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252":"פרמטרים מבוקשים: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252","2 (reply, from a server)":"2 (תשובה, משרת)","Message type: 2 (Offer)":"סוג הודעה: 2 (Offer)","Server identifier: 192.168.1.1":"מזהה שרת: 192.168.1.1","Lease time: 86,400 s (24 h)":"זמן חכירה: 86,400 s (24 h)","Renewal time (T1): 43,200 s (12 h)":"זמן חידוש (T1): 43,200 s (12 h)","Rebinding time (T2): 75,600 s (21 h)":"זמן קישור מחדש (T2): 75,600 s (21 h)","Subnet mask: 255.255.255.0":"מסכת תת־רשת: 255.255.255.0","Broadcast address: 192.168.1.255":"כתובת שידור: 192.168.1.255","DNS server: 8.8.8.8":"שרת DNS: 8.8.8.8","Message type: 3 (Request)":"סוג הודעה: 3 (Request)","Requested address: 192.168.1.10":"כתובת מבוקשת: 192.168.1.10","Client FQDN: alice-laptop":"FQDN של הלקוח: alice-laptop","Message type: 5 (ACK)":"סוג הודעה: 5 (ACK)","Network Diagnostics":"אבחון רשת","Ping / probe":"Ping / בדיקה","Echo reply":"תשובת הד","Error report":"דיווח שגיאה","Internet Control Message Protocol":"פרוטוקול הודעות בקרה באינטרנט","ICMP is how the network reports back: a router says a packet’s time ran out, a server says nothing is listening on a port. Tools like ping and traceroute are built from these messages. It travels inside IP but carries no application data.":"ICMP הוא הדרך שבה הרשת מדווחת בחזרה: נתב אומר שהזמן של חבילה נגמר, שרת אומר ששום דבר לא מאזין בפורט. כלים כמו ping ו־traceroute בנויים מההודעות האלה. הוא נוסע בתוך IP אבל לא נושא נתוני יישום.","Carried in":"נישא בתוך","IP (protocol 1)":"IP (פרוטוקול 1)","A type and a code":"סוג וקוד",Tools:"כלים",Often:"לעיתים קרובות","Filtered by firewalls":"מסונן על ידי חומות אש","The network answered":"הרשת ענתה","Replies, expiries and errors":"תשובות, פקיעות ושגיאות","An echo request measured the round trip, packets with a small TTL made each router on the path identify itself, and a closed port was reported straight back. Press REPLAY to watch it again.":"בקשת הד מדדה את זמן הסבב, חבילות עם TTL קטן גרמו לכל נתב בדרך להזדהות, ופורט סגור דווח ישר בחזרה. לחצו על ״שוב״ כדי לצפות שוב.","Round trip":"סבב הלוך ושוב",Path:"מסלול","12 routers, server at hop 13":"12 נתבים, השרת בקפיצה 13","Types used":"סוגים בשימוש","8, 0, 11 and 3":"8, 0, 11 ו־3","Reply TTL":"TTL של התשובה",Ping:"Ping","Echo request":"בקשת הד","“ping -n 1 203.0.113.10” sends one ICMP echo request (plain ping sends four, a second apart): type 8, code 0, with an identifier, a sequence number and 32 bytes of filler. The server’s system answers by itself, no application needed.":"״ping -n 1 203.0.113.10״ שולח בקשת הד אחת של ICMP (ping רגיל שולח ארבע, בהפרש של שנייה): סוג 8, קוד 0, עם מזהה, מספר רצף ו־32 בתים של מילוי. המערכת של השרת עונה בעצמה, בלי צורך באפליקציה.","Type, code":"סוג, קוד","8, 0 (echo request)":"8, 0 (בקשת הד)","type 8 · seq 1":"סוג 8 · seq 1","32 bytes of data":"32 בתים של נתונים","Echo Reply":"תשובת הד","Round-trip time":"זמן סבב","The server sends back an echo reply, type 0, with the same identifier, sequence number and data. Ping prints the time it took and the TTL the reply arrived with: “bytes=32 time=34ms TTL=52”.":"השרת שולח בחזרה תשובת הד, סוג 0, עם אותו מזהה, מספר רצף ונתונים. ping מדפיס את הזמן שלקח ואת ה־TTL שאיתו הגיעה התשובה: ״bytes=32 time=34ms TTL=52״.","0, 0 (echo reply)":"0, 0 (תשובת הד)","TTL on arrival":"TTL בהגעה","type 0 · seq 1":"סוג 0 · seq 1","same 32 bytes back":"אותם 32 בתים בחזרה","The first router answers":"הנתב הראשון עונה","“ping -n 1 -i 1” sends the same request with a TTL of 1. The home router lowers it to 0, so it must drop the packet, and it sends back a Time Exceeded message from its own address: “Reply from 192.168.1.1: TTL expired in transit.”":"״ping -n 1 -i 1״ שולח את אותה בקשה עם TTL של 1. הנתב הביתי מוריד אותו ל־0, ולכן הוא חייב להשליך את החבילה, והוא שולח בחזרה הודעת Time Exceeded מהכתובת שלו: ״Reply from 192.168.1.1: TTL expired in transit.״","Sent with":"נשלח עם","Dropped by":"הושלך על ידי","11, 0 (time exceeded)":"11, 0 (הזמן פג)","echo request":"בקשת הד","expires at the first router":"פג בנתב הראשון","type 11 · from 192.168.1.1":"סוג 11 · מ־192.168.1.1","quotes the dropped header":"מצטט את הכותרת שהושלכה","The next router answers":"הנתב הבא עונה","With “-i 2”, the home router lowers the TTL to 1 and forwards it. The first router at the internet provider lowers it to 0 and reports back from 198.51.100.1. The home router translates the report back to the laptop like any reply.":"עם ״-i 2״, הנתב הביתי מוריד את ה־TTL ל־1 ומעביר הלאה. הנתב הראשון אצל ספק האינטרנט מוריד אותו ל־0 ומדווח בחזרה מ־198.51.100.1. הנתב הביתי מתרגם את הדיווח בחזרה למחשב הנייד כמו כל תשובה.","ISP router 198.51.100.1":"נתב הספק 198.51.100.1","expires at the second router":"פג בנתב השני","type 11 · from 198.51.100.1":"סוג 11 · מ־198.51.100.1","That’s Traceroute":"זה Traceroute","TTL 1, 2, 3 … until it arrives":"TTL 1, 2, 3 … עד שמגיעים","tracert automates this: it raises the TTL by one each time, sends three probes per hop and lists who reports back. Hops 3 to 12 work the same way, and with TTL 13 the request finally reaches the server, which replies normally.":"tracert עושה את זה אוטומטית: הוא מעלה את ה־TTL באחד בכל פעם, שולח שלוש בדיקות לכל קפיצה ומציג מי מדווח בחזרה. קפיצות 3 עד 12 עובדות באותה צורה, ועם TTL 13 הבקשה מגיעה סוף־סוף לשרת, שעונה כרגיל.","12 routers, then the server":"12 נתבים, ואז השרת","Per hop":"לכל קפיצה","3 probes":"3 בדיקות","On Linux":"ב־Linux","traceroute sends UDP":"traceroute שולח UDP","enough hops to arrive":"מספיק קפיצות כדי להגיע","the server itself answers":"השרת עצמו עונה","end of the route":"סוף המסלול",Unreachable:"לא ניתן להגיע","Nothing listening on that port":"שום דבר לא מאזין בפורט הזה","An app sends a UDP datagram to port 9999, where nothing is listening. The server can’t deliver it, so it replies with Destination Unreachable, code 3 (port unreachable), quoting the start of the datagram. Many firewalls drop such packets silently instead.":"אפליקציה שולחת דאטגרמת UDP לפורט 9999, ששום דבר לא מאזין בו. השרת לא יכול למסור אותה, ולכן הוא עונה ב־Destination Unreachable, קוד 3 (הפורט לא זמין), ומצטט את תחילת הדאטגרמה. חומות אש רבות משליכות חבילות כאלה בשקט במקום זאת.","3, 3 (port unreachable)":"3, 3 (הפורט לא זמין)","Other codes":"קודים אחרים","0 net, 1 host, 4 too big":"0 רשת, 1 מארח, 4 גדול מדי",Firewalls:"חומות אש","Often silent instead":"לעיתים קרובות שותקות במקום","to port 9999":"לפורט 9999","nothing listening there":"שום דבר לא מאזין שם","type 3 · code 3":"סוג 3 · קוד 3","port unreachable":"הפורט לא זמין","ICMP · Echo request":"ICMP · בקשת הד",Code:"קוד","Covers the whole ICMP message.":"מכסה את כל הודעת ה־ICMP.",Identifier:"מזהה","Matches replies to this ping program.":"מתאים תשובות לתוכנית ה־ping הזו.","Windows counts up across every ping it sends.":"Windows סופר כלפי מעלה לאורך כל ping שהוא שולח.","Windows ping’s filler: the alphabet, a to w, then again.":"המילוי של ping ב־Windows: האלפבית, מ־a עד w, ושוב מההתחלה.","ICMP · Echo reply":"ICMP · תשובת הד","Sent back exactly as it came.":"נשלח בחזרה בדיוק כפי שהגיע.","ICMP · Time exceeded (TTL reached 0)":"ICMP · הזמן פג (ה־TTL הגיע ל־0)","Time exceeded (TTL reached 0)":"הזמן פג (ה־TTL הגיע ל־0)",Unused:"לא בשימוש","Original packet":"החבילה המקורית","Its source, destination":"המקור והיעד שלה","its IP header and first 8 bytes (28 bytes)":"כותרת ה־IP שלה ו־8 הבתים הראשונים (28 בתים)","App data":"נתוני אפליקציה","What the app sent; nothing on the server is listening for it.":"מה שהאפליקציה שלחה; שום דבר בשרת לא מאזין לזה.","ICMP · Destination unreachable (port unreachable)":"ICMP · היעד לא זמין (הפורט לא זמין)","Destination unreachable (port unreachable)":"היעד לא זמין (הפורט לא זמין)","Sending Email":"שליחת דואר","SMTP command":"פקודת SMTP","SMTP reply":"תשובת SMTP","SMTP moves email: from your mail app to your provider’s server, and from that server to the recipient’s. It is a conversation of short text commands, each answered with a three-digit reply code. Reading mail is a different job, done with IMAP or POP3.":"SMTP מעביר דואר אלקטרוני: מאפליקציית הדואר שלכם לשרת של הספק שלכם, ומהשרת הזה לשרת של הנמען. זו שיחה של פקודות טקסט קצרות, שכל אחת מהן נענית בקוד תשובה בן שלוש ספרות. קריאת דואר היא עבודה אחרת, שנעשית עם IMAP או POP3.","465/587 submit, 25 relay":"465/587 הגשה, 25 ממסר","TCP, usually with TLS":"TCP, בדרך כלל עם TLS",Commands:"פקודות",Replies:"תשובות","2xx ok, 3xx go on, 4/5xx error":"2xx תקין, 3xx להמשיך, 4/5xx שגיאה","Mail delivered":"הדואר נמסר","Two hops, one message":"שתי קפיצות, הודעה אחת","Alice’s app handed the message to her provider over an encrypted, logged-in connection. The provider found Bob’s mail server in DNS and relayed it there, upgrading that link to TLS. It now waits in Bob’s mailbox until he reads it with IMAP or POP3.":"האפליקציה של אליס מסרה את ההודעה לספק שלה בחיבור מוצפן ומאומת. הספק מצא ב־DNS את שרת הדואר של בוב והעביר אליו את ההודעה, אחרי ששדרג את הקישור הזה ל־TLS. עכשיו היא מחכה בתיבת הדואר של בוב עד שהוא יקרא אותה עם IMAP או POP3.","Laptop → provider → Bob’s":"מחשב נייד ← ספק ← השרת של בוב",Submission:"הגשה","Port 465, TLS, login":"פורט 465, TLS, התחברות",Relay:"ממסר","Port 25, STARTTLS":"פורט 25, STARTTLS","Checks at Bob’s":"בדיקות אצל בוב","Connect Securely":"התחברות מאובטחת","Alice presses Send. Her mail app connects to her provider’s submission server, smtp.example.com, on port 465. On this port TLS starts immediately, so the whole SMTP conversation, including her password, is encrypted.":"אליס לוחצת על ״שליחה״. אפליקציית הדואר שלה מתחברת לשרת ההגשה של הספק שלה, smtp.example.com, בפורט 465. בפורט הזה TLS מתחיל מיד, ולכן כל שיחת ה־SMTP, כולל הסיסמה שלה, מוצפנת.","TLS from the start":"TLS מההתחלה","SMTP inside TLS":"SMTP בתוך TLS","Greeting & Login":"ברכה והתחברות","EHLO, then AUTH":"EHLO, ואז AUTH","The server greets with code 220. The app says EHLO and the server lists what it supports, including AUTH. The app logs in with AUTH PLAIN (user name and password, base64-encoded) and gets 235: authenticated.":"השרת מברך עם קוד 220. האפליקציה אומרת EHLO והשרת מפרט במה הוא תומך, כולל AUTH. האפליקציה מתחברת עם AUTH PLAIN (שם משתמש וסיסמה, בקידוד base64) ומקבלת 235: מאומת.",Greeting:"ברכה",Capabilities:"יכולות","Login result":"תוצאת ההתחברות","user and password, base64":"משתמש וסיסמה, base64","Send the Message":"שליחת ההודעה","Envelope, then content":"מעטפה, ואז תוכן","MAIL FROM and RCPT TO are the envelope: sender and recipient. PIPELINING lets all three commands share one packet. After 354 comes the message, ended by a line holding just a dot.":"MAIL FROM ו־RCPT TO הם המעטפה: השולח והנמען. PIPELINING מאפשר לשלוש הפקודות לחלוק חבילה אחת. אחרי 354 מגיעה ההודעה, שמסתיימת בשורה שיש בה רק נקודה.",Envelope:"מעטפה","Content ends":"סוף התוכן","A line with only “.”":"שורה עם ״.״ בלבד",Result:"תוצאה","… message …":"… ההודעה …","Find Bob’s Server":"מציאת השרת של בוב","An MX lookup in DNS":"חיפוש MX ב־DNS","Alice’s provider now has to deliver to example.org. It asks DNS for that domain’s MX record, which names the server that accepts its mail, then looks up that server’s address.":"הספק של אליס צריך עכשיו למסור ל־example.org. הוא שואל את ה־DNS על רשומת ה־MX של הדומיין, שמציינת את השרת שמקבל את הדואר שלו, ואז מחפש את הכתובת של אותו שרת.","MX record":"רשומת MX","Asked by":"נשאל על ידי","Alice’s provider":"הספק של אליס","Server to Server":"משרת לשרת","Port 25, upgraded with STARTTLS":"פורט 25, משודרג עם STARTTLS","The provider connects to mx.example.org on port 25. This conversation starts in plain text: the greeting and EHLO reply advertise STARTTLS, the provider asks for it, gets 220 and both sides switch to TLS.":"הספק מתחבר ל־mx.example.org בפורט 25. השיחה הזו מתחילה כטקסט גלוי: הברכה והתשובה ל־EHLO מפרסמות STARTTLS, הספק מבקש אותו, מקבל 220 ושני הצדדים עוברים ל־TLS.","Starts as":"בהתחלה","Plain text":"טקסט גלוי",Upgrade:"שדרוג",Deliver:"מסירה","The same transaction again":"אותה טרנזקציה שוב","With TLS on, the provider repeats EHLO, then the envelope and the message, now with a DKIM signature and a Received header added. Bob’s server checks SPF, DKIM and DMARC and accepts it.":"כש־TLS פעיל, הספק חוזר על EHLO, ואז על המעטפה וההודעה, עכשיו עם חתימת DKIM וכותרת Received שנוספו. השרת של בוב בודק SPF, DKIM ו־DMARC ומקבל אותה.","Login needed":"נדרשת התחברות","No (server to server)":"לא (משרת לשרת)","1,316 bytes (signed)":"1,316 בתים (חתום)","Server Hello + encrypted handshake, 2 segments":"Server Hello + לחיצת יד מוצפנת, 2 מקטעים","250 capabilities (PIPELINING, SIZE, AUTH …)":"250 יכולות (PIPELINING, SIZE, AUTH …)","AUTH PLAIN (credentials)":"AUTH PLAIN (פרטי הזדהות)","MAIL FROM, RCPT TO, DATA (pipelined)":"MAIL FROM, RCPT TO, DATA (ברצף, בלי המתנה)","Message (316 bytes), then “.”":"הודעה (316 בתים), ואז ״.״","250 capabilities (PIPELINING, STARTTLS …)":"250 יכולות (PIPELINING, STARTTLS …)","250 capabilities (PIPELINING, SIZE …)":"250 יכולות (PIPELINING, SIZE …)","Message (1,316 bytes), then “.”":"הודעה (1,316 בתים), ואז ״.״","What this client supports. Its exact contents vary from client to client; this is an example.":"במה הלקוח הזה תומך. התוכן המדויק משתנה מלקוח ללקוח; זו דוגמה.","up to 512 bytes":"עד 512 בתים","The server’s choices and its key share.":"הבחירות של השרת ושיתוף המפתח שלו.","Encrypted Extensions, Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions, Certificate (השרשרת), Certificate Verify (החתימה), Finished","Alice’s message (316 bytes), then a line holding only “.”":"ההודעה של אליס (316 בתים), ואז שורה שיש בה רק ״.״","example.org, type MX, class IN":"example.org, סוג MX, מחלקה IN","mx.example.org, type A, class IN":"mx.example.org, סוג A, מחלקה IN",Timestamps:"חותמות זמן","Used to measure round trips; both sides offered them.":"משמשות למדידת סבבים; שני הצדדים הציעו אותן.","The signed message (1,316 bytes), then a line holding only “.”":"ההודעה החתומה (1,316 בתים), ואז שורה שיש בה רק ״.״","Downloading Email":"הורדת דואר","POP3 command":"פקודת POP3","POP3 reply":"תשובת POP3","Post Office Protocol, version 3":"פרוטוקול סניף הדואר, גרסה 3","POP3 lets a mail app download messages from a mailbox on a server. It was designed for one device that fetches mail and then removes it from the server. Commands are short words, and every reply starts with +OK or -ERR.":"POP3 מאפשר לאפליקציית דואר להוריד הודעות מתיבת דואר בשרת. הוא תוכנן למכשיר אחד שמביא את הדואר ואז מוחק אותו מהשרת. הפקודות הן מילים קצרות, וכל תשובה מתחילה ב־+OK או ב־-ERR.",Model:"מודל","Download, then delete":"הורדה, ואז מחיקה","Mail downloaded":"הדואר הורד","And gone from the server":"ונעלם מהשרת","Bob’s app logged in, saw two messages, downloaded the first and deleted it, which the server carried out at QUIT. That message now lives only on this laptop, which is why POP3 suits one device and IMAP suits several.":"האפליקציה של בוב התחברה, ראתה שתי הודעות, הורידה את הראשונה ומחקה אותה, והשרת ביצע את המחיקה ב־QUIT. ההודעה הזו נמצאת עכשיו רק במחשב הנייד הזה, ולכן POP3 מתאים למכשיר אחד ו־IMAP מתאים לכמה מכשירים.","2 waiting, 1 downloaded":"2 ממתינות, 1 הורדה",Deleted:"נמחקה","At QUIT (UPDATE state)":"ב־QUIT (מצב UPDATE)","Best for":"מתאים במיוחד","A single device":"מכשיר יחיד","Bob’s mail app connects to pop.example.org on port 995, where TLS starts right away. Inside it, the server greets with +OK. (On port 110 the session starts in plain text and is upgraded with the STLS command.)":"אפליקציית הדואר של בוב מתחברת ל־pop.example.org בפורט 995, שבו TLS מתחיל מיד. בתוכו, השרת מברך עם +OK. (בפורט 110 הסשן מתחיל כטקסט גלוי ומשודרג עם הפקודה STLS.)","USER, then PASS":"USER, ואז PASS","The app sends the user name with USER and the password with PASS. Each command gets its own +OK. Because the session is inside TLS, the password isn’t readable on the way.":"האפליקציה שולחת את שם המשתמש עם USER ואת הסיסמה עם PASS. כל פקודה מקבלת +OK משלה. מכיוון שהסשן נמצא בתוך TLS, הסיסמה לא קריאה בדרך.","Protected by":"מוגן על ידי","Check the Mailbox":"בדיקת תיבת הדואר","STAT and LIST":"STAT ו־LIST","STAT returns the number of messages and their total size: 2 messages, 5120 bytes. LIST gives each message’s number and size, ending with a line holding just a dot.":"STAT מחזיר את מספר ההודעות ואת הגודל הכולל שלהן: 2 הודעות, 5120 בתים. LIST נותן את המספר והגודל של כל הודעה, ומסתיים בשורה שיש בה רק נקודה.","Message 1":"הודעה 1","Message 2":"הודעה 2",Download:"הורדה","RETR 1 asks for the first message. The server answers +OK with its size, then the message and a closing dot: 1904 bytes plus the reply line, two TCP segments.":"RETR 1 מבקש את ההודעה הראשונה. השרת עונה +OK עם הגודל שלה, ואז את ההודעה ונקודה סוגרת: 1904 בתים ועוד שורת התשובה, שני מקטעי TCP.",Command:"פקודה","Delete & Quit":"מחיקה ויציאה","Deleted only at QUIT":"נמחקת רק ב־QUIT","DELE 1 only marks the message. The server removes it when the app says QUIT: if the connection dropped before that, nothing would be deleted. Many apps offer “leave a copy on the server”, which skips DELE.":"DELE 1 רק מסמן את ההודעה. השרת מוחק אותה כשהאפליקציה אומרת QUIT: אם החיבור היה נופל לפני כן, שום דבר לא היה נמחק. אפליקציות רבות מציעות ״להשאיר עותק בשרת״, מה שמדלג על DELE.","Marks message 1":"מסמן את הודעה 1",Removed:"הוסרה",Option:"אפשרות","Leave a copy on server":"להשאיר עותק בשרת","PASS (password)":"PASS (סיסמה)","+OK 1904 octets, message, “.” (2 segments)":"+OK 1904 octets, ההודעה, ״.״ (2 מקטעים)","+OK 1904 octets, the 1,904-byte message, then a line holding only “.”":"+OK 1904 octets, ההודעה בת 1,904 הבתים, ואז שורה שיש בה רק ״.״","Mail That Stays in Sync":"דואר שנשאר מסונכרן","IMAP command":"פקודת IMAP","IMAP response":"תגובת IMAP","Internet Message Access Protocol":"פרוטוקול גישה להודעות אינטרנט","IMAP lets mail apps work with a mailbox that stays on the server. Folders, read and flagged marks and deletions are kept there, so a phone, a laptop and webmail all see the same mailbox. The server can also tell an app about new mail as it arrives.":"IMAP מאפשר לאפליקציות דואר לעבוד עם תיבת דואר שנשארת בשרת. תיקיות, סימוני ״נקרא״ ו״מסומן״ ומחיקות נשמרים שם, כך שטלפון, מחשב נייד ודואר ווב רואים כולם את אותה תיבה. השרת יכול גם להודיע לאפליקציה על דואר חדש ברגע שהוא מגיע.","Mail stays on the server":"הדואר נשאר בשרת",Syncs:"מסנכרן","Folders and flags":"תיקיות ודגלים","Mailbox in sync":"תיבת הדואר מסונכרנת","Read once, read everywhere":"נקרא פעם אחת, נקרא בכל מקום","Bob’s app opened his inbox, read a message, which marked it \\Seen on the server for all his devices, and then waited with IDLE until the server announced new mail. Nothing was deleted: the server still holds everything.":"האפליקציה של בוב פתחה את תיבת הדואר הנכנס שלו, קראה הודעה, מה שסימן אותה \\Seen בשרת עבור כל המכשירים שלו, ואז המתינה עם IDLE עד שהשרת הודיע על דואר חדש. שום דבר לא נמחק: השרת עדיין מחזיק הכול.","2, then 3 (new mail)":"2, ואז 3 (דואר חדש)","Read mark":"סימון ״נקרא״","\\Seen, stored on server":"\\Seen, נשמר בשרת","New mail":"דואר חדש","Pushed during IDLE":"נדחף בזמן IDLE","Bob’s app connects to imap.example.org on port 993, where TLS starts right away. The server greets with an untagged “* OK” line that also lists its capabilities, such as IDLE.":"האפליקציה של בוב מתחברת ל־imap.example.org בפורט 993, שבו TLS מתחיל מיד. השרת מברך בשורת ״* OK״ ללא תג, שמפרטת גם את היכולות שלו, כמו IDLE.","Commands carry tags":"לפקודות יש תגים","Every command starts with a tag the app chooses, like a1, and the server ends its answer with the same tag. That way several commands can be in flight and each reply is matched up. Lines starting with * are untagged data.":"כל פקודה מתחילה בתג שהאפליקציה בוחרת, כמו a1, והשרת מסיים את התשובה שלו באותו תג. כך כמה פקודות יכולות להיות בדרך בו־זמנית וכל תשובה מותאמת לפקודה שלה. שורות שמתחילות ב־* הן נתונים ללא תג.",Tags:"תגים","Match replies to commands":"מתאימים תשובות לפקודות","Open the Inbox":"פתיחת תיבת הדואר הנכנס","SELECT a folder":"SELECT לתיקייה","SELECT INBOX opens the folder. The server reports the message count, the flags it supports and the first unread message, then confirms the folder is open read-write.":"SELECT INBOX פותח את התיקייה. השרת מדווח על מספר ההודעות, הדגלים שהוא תומך בהם וההודעה הראשונה שלא נקראה, ואז מאשר שהתיקייה פתוחה לקריאה וכתיבה.","First unread":"ראשונה שלא נקראה",Access:"גישה","Read a Message":"קריאת הודעה","FETCH, and the \\Seen flag":"FETCH, והדגל \\Seen","FETCH 2 BODY[] downloads message 2 (three TCP segments). That sets its \\Seen flag on the server, so it shows as read on Bob’s phone too, and the message stays there.":"FETCH 2 BODY[] מוריד את הודעה 2 (שלושה מקטעי TCP). זה מציב את הדגל \\Seen שלה בשרת, כך שהיא מופיעה כנקראה גם בטלפון של בוב, וההודעה נשארת שם.","Flag set":"דגל שהוצב","\\Seen (on the server)":"\\Seen (בשרת)","Wait for New Mail":"המתנה לדואר חדש","IDLE: the server pushes":"IDLE: השרת דוחף","IDLE tells the server “let me know when something changes”. About 42 seconds later Alice’s message arrives and the server pushes “* 3 EXISTS” straight away. The app ends IDLE with DONE and can fetch the new mail.":"IDLE אומר לשרת ״תודיע לי כשמשהו משתנה״. כ־42 שניות אחר כך ההודעה של אליס מגיעה והשרת דוחף מיד ״* 3 EXISTS״. האפליקציה מסיימת את IDLE עם DONE ויכולה להביא את הדואר החדש.","Server says":"השרת אומר","* 3 EXISTS (new mail)":"* 3 EXISTS (דואר חדש)","Ended by":"הסתיים על ידי","a1 LOGIN (user and password)":"a1 LOGIN (משתמש וסיסמה)","* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, the 3,216-byte message, then a3 OK FETCH completed":"* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, ההודעה בת 3,216 הבתים, ואז a3 OK FETCH completed","Transferring Files":"העברת קבצים","FTP command":"פקודת FTP","FTP reply":"תשובת FTP","File data":"נתוני קובץ","FTP moves files between a client and a server. It is unusual in using two TCP connections: one for commands and replies, and a fresh one for each file or listing. It dates from the early 1970s and sends everything, passwords included, as plain text.":"FTP מעביר קבצים בין לקוח לשרת. הוא חריג בכך שהוא משתמש בשני חיבורי TCP: אחד לפקודות ולתשובות, וחיבור חדש לכל קובץ או רשימה. הוא מתחילת שנות ה־70 ושולח הכול, כולל סיסמאות, כטקסט גלוי.","21 control, data varies":"21 בקרה, הנתונים משתנים",Connections:"חיבורים","Control + one per transfer":"בקרה + אחד לכל העברה",Encryption:"הצפנה","None (plain text)":"אין (טקסט גלוי)","Safer options":"אפשרויות בטוחות יותר","File downloaded":"הקובץ הורד","Two connections, no encryption":"שני חיבורים, בלי הצפנה","Commands went over the control connection, the file over its own data connection, and closing that connection marked the end of the file. Anyone on the path could have read the password and the file, which is why SFTP or FTPS is used today.":"הפקודות עברו בחיבור הבקרה, הקובץ בחיבור נתונים משלו, וסגירת החיבור הזה סימנה את סוף הקובץ. כל מי שבדרך יכול היה לקרוא את הסיסמה ואת הקובץ, ולכן היום משתמשים ב־SFTP או ב־FTPS.","2 (control + data)":"2 (בקרה + נתונים)",File:"קובץ","4,000 bytes, 3 segments":"4,000 בתים, 3 מקטעים",Password:"סיסמה","Sent in plain text":"נשלחת כטקסט גלוי","Use instead":"במקום זה","Control Connection":"חיבור בקרה","Port 21, plain text":"פורט 21, טקסט גלוי","The FTP app opens a TCP connection to ftp.example.com on port 21. This control connection carries commands and replies for the whole session. The server greets with 220. Like SMTP, every reply starts with a three-digit code.":"אפליקציית ה־FTP פותחת חיבור TCP ל־ftp.example.com בפורט 21. חיבור הבקרה הזה נושא פקודות ותשובות לאורך כל הסשן. השרת מברך עם 220. כמו ב־SMTP, כל תשובה מתחילה בקוד בן שלוש ספרות.","USER and PASS, readable by anyone":"USER ו־PASS, קריאים לכל אחד","The app sends USER, the server asks for the password with 331, and PASS sends it. Nothing is encrypted, so the user name and password cross every network on the way as readable text.":"האפליקציה שולחת USER, השרת מבקש את הסיסמה עם 331, ו־PASS שולח אותה. שום דבר לא מוצפן, ולכן שם המשתמש והסיסמה חוצים כל רשת בדרך כטקסט קריא.","Visible to":"גלוי עבור","Anyone on the path":"כל מי שבדרך","Passive Mode":"מצב פסיבי","The server names a data port":"השרת מציין פורט נתונים","TYPE I asks for a byte-for-byte binary copy. PASV asks the server to open a port for the data connection. The reply encodes the address and port as six numbers: 195 × 256 + 149 = port 50069. The laptop connects out, which works through NAT.":"TYPE I מבקש עותק בינארי זהה בית אחר בית. PASV מבקש מהשרת לפתוח פורט לחיבור הנתונים. התשובה מקודדת את הכתובת והפורט כשישה מספרים: 195 × 256 + 149 = פורט 50069. המחשב הנייד מתחבר החוצה, וזה עובד דרך NAT.","Data port":"פורט נתונים","Active mode":"מצב אקטיבי","Server dials in: NAT blocks":"השרת מתקשר פנימה: NAT חוסם","Data Connection":"חיבור נתונים","A second TCP connection":"חיבור TCP שני","The app opens a second TCP connection, to port 50069, and asks for the file on the control connection with RETR. The server answers 150 there and starts sending the file over the new connection.":"האפליקציה פותחת חיבור TCP שני, לפורט 50069, ומבקשת את הקובץ בחיבור הבקרה עם RETR. השרת עונה שם 150 ומתחיל לשלוח את הקובץ בחיבור החדש.","Data to":"נתונים אל","The File Arrives":"הקובץ מגיע","Closing the connection ends it":"סגירת החיבור מסיימת אותו","The 4,000 bytes arrive in 3 TCP segments. FTP sends no length marker in the data itself: the server closes the data connection to mark the end of the file. Once the laptop has acknowledged everything, the server confirms with 226 on the control connection.":"4,000 הבתים מגיעים ב־3 מקטעי TCP. FTP לא שולח סימון אורך בתוך הנתונים עצמם: השרת סוגר את חיבור הנתונים כדי לסמן את סוף הקובץ. אחרי שהמחשב הנייד אישר הכול, השרת מאשר עם 226 בחיבור הבקרה.","End of file":"סוף הקובץ","Data connection closed":"חיבור הנתונים נסגר","4,000 bytes, readable by anyone":"4,000 בתים, קריאים לכל אחד","end of file:":"סוף הקובץ:","data connection closed":"חיבור הנתונים נסגר",Quit:"יציאה","Close the control connection":"סגירת חיבור הבקרה","QUIT ends the session and the server says goodbye with 221. For anything sensitive, SFTP (a different protocol, run over SSH) or FTPS (FTP inside TLS) gives the same job encryption.":"QUIT מסיים את הסשן והשרת נפרד עם 221. לכל דבר רגיש, SFTP (פרוטוקול אחר, שרץ מעל SSH) או FTPS (FTP בתוך TLS) עושים את אותה עבודה עם הצפנה.","Encrypted cousins":"קרובי משפחה מוצפנים","FTP data":"נתוני FTP","The file itself, unencrypted: anyone on the path could read it.":"הקובץ עצמו, לא מוצפן: כל מי שבדרך יכול היה לקרוא אותו.","Secure Remote Login":"התחברות מרחוק מאובטחת","Plain setup":"הקמה גלויה","From laptop":"מהמחשב הנייד","From server":"מהשרת","Some packets not shown":"חלק מהחבילות לא מוצגות","SSH gives you an encrypted, authenticated connection to another computer, to run commands on it, copy files (SFTP, scp) or carry other connections. The server proves who it is with a host key; you prove who you are with a key pair or a password.":"SSH נותן לכם חיבור מוצפן ומאומת למחשב אחר, כדי להריץ עליו פקודות, להעתיק קבצים (SFTP, scp) או להעביר חיבורים אחרים. השרת מוכיח מי הוא באמצעות מפתח מארח; אתם מוכיחים מי אתם באמצעות זוג מפתחות או סיסמה.","Server proves":"השרת מוכיח","Host key (known_hosts)":"מפתח מארח (known_hosts)","You prove":"אתם מוכיחים","Key pair or password":"זוג מפתחות או סיסמה","Logged in securely":"מחוברים בצורה מאובטחת","Encrypted from the key exchange on":"מוצפן מהחלפת המפתחות והלאה","The two sides agreed on algorithms, built shared keys with a post-quantum hybrid exchange, and the server proved its identity with its host key. Alice proved hers by signing with a private key that never left the laptop, then typed a command, one packet per key.":"שני הצדדים הסכימו על אלגוריתמים, בנו מפתחות משותפים בהחלפה היברידית פוסט־קוונטית, והשרת הוכיח את זהותו עם מפתח המארח שלו. אליס הוכיחה את זהותה בחתימה עם מפתח פרטי שמעולם לא עזב את המחשב הנייד, ואז הקלידה פקודה, חבילה אחת לכל הקשה.",Login:"התחברות","Ed25519 key, no password":"מפתח Ed25519, בלי סיסמה","Say Hello":"אומרים שלום","Versions, in plain text":"גרסאות, בטקסט גלוי","Alice runs “ssh alice@server.example.com”. After the TCP handshake on port 22, each side sends one line of plain text naming the SSH protocol version (2.0) and its software. Everything else in SSH is binary.":"אליס מריצה ״ssh alice@server.example.com״. אחרי לחיצת היד של TCP בפורט 22, כל צד שולח שורה אחת של טקסט גלוי שמציינת את גרסת פרוטוקול SSH (2.0) ואת התוכנה שלו. כל השאר ב־SSH בינארי.","Agree on Algorithms":"הסכמה על אלגוריתמים","KEXINIT lists, first match wins":"רשימות KEXINIT, ההתאמה הראשונה מנצחת","Each side sends a KEXINIT listing every algorithm it supports, in order of preference, for key exchange, host keys, encryption, integrity and compression. In each category the first algorithm on the laptop’s list that the server also supports is chosen.":"כל צד שולח KEXINIT שמפרט כל אלגוריתם שהוא תומך בו, לפי סדר העדפה, להחלפת מפתחות, מפתחות מארח, הצפנה, שלמות ודחיסה. בכל קטגוריה נבחר האלגוריתם הראשון ברשימה של המחשב הנייד שגם השרת תומך בו.","Host key":"מפתח מארח","server’s algorithm lists":"רשימות האלגוריתמים של השרת","in order of preference":"לפי סדר העדפה","laptop’s algorithm lists":"רשימות האלגוריתמים של המחשב הנייד","Key Exchange":"החלפת מפתחות","Shared keys, and a host key check":"מפתחות משותפים, ובדיקת מפתח המארח","The laptop sends its half of a hybrid exchange: a Streamlined NTRU Prime key, chosen to resist future quantum computers, plus an X25519 key. The server answers with its half, its host key and a signature over the exchange. NEWKEYS switches encryption on.":"המחשב הנייד שולח את החצי שלו בהחלפה היברידית: מפתח Streamlined NTRU Prime, שנבחר כדי לעמוד בפני מחשבים קוונטיים עתידיים, ועוד מפתח X25519. השרת עונה עם החצי שלו, מפתח המארח שלו וחתימה על ההחלפה. NEWKEYS מפעיל את ההצפנה.",Hybrid:"היברידי","Matches known_hosts":"תואם ל־known_hosts","First visit":"ביקור ראשון","ssh asks you to confirm":"ssh מבקש מכם לאשר","public keys":"מפתחות ציבוריים","its half, its host key":"החצי שלו, מפתח המארח שלו","and a signature":"וחתימה","Log In with a Key":"התחברות עם מפתח","Sign, don’t send a secret":"חותמים, לא שולחים סוד","The server lists the login methods it accepts. The laptop offers Alice’s public key, and the server says it would accept it. The laptop then signs this session with the private key, which never leaves the laptop. The server checks the signature against authorized_keys.":"השרת מפרט את שיטות ההתחברות שהוא מקבל. המחשב הנייד מציע את המפתח הציבורי של אליס, והשרת אומר שהוא יקבל אותו. אז המחשב הנייד חותם על הסשן הזה עם המפתח הפרטי, שאף פעם לא עוזב את המחשב הנייד. השרת בודק את החתימה מול authorized_keys.",Methods:"שיטות","Ed25519, private stays here":"Ed25519, הפרטי נשאר כאן","Checked with":"נבדק מול","alice’s public key":"המפתח הציבורי של alice","would you accept it?":"תקבל אותו?","yes, that key":"כן, המפתח הזה","is in authorized_keys":"נמצא ב־authorized_keys","same key, plus a signature":"אותו מפתח, ועוד חתימה","made with the private key":"שנוצרה עם המפתח הפרטי","logged in":"מחובר","Open a Session":"פתיחת סשן","Channels inside one connection":"ערוצים בתוך חיבור אחד","One SSH connection can carry many channels: a shell, file transfers, forwarded ports. The laptop opens a session channel, then asks for a terminal and a shell (not shown), and the server sends its welcome text and a prompt.":"חיבור SSH אחד יכול לשאת ערוצים רבים: מעטפת, העברות קבצים, פורטים מועברים. המחשב הנייד פותח ערוץ סשן, ואז מבקש מסוף ומעטפת (לא מוצג), והשרת שולח את טקסט הפתיחה שלו ושורת פקודה.",Channel:"ערוץ",session:"session","Then asks for":"אחר כך מבקש","A terminal and a shell":"מסוף ומעטפת","Also possible":"אפשרי גם","SFTP, port forwarding":"SFTP, העברת פורטים","open a channel:":"פתיחת ערוץ:","channel open":"הערוץ נפתח","Type a Command":"הקלדת פקודה","Every key is a packet":"כל הקשה היא חבילה","Alice types pwd. Each key goes out at once in its own encrypted packet, and the server sends the character back to be shown (the echo). Since 9.5, OpenSSH sends keys on a 20 ms beat and adds decoy packets, so typing rhythm is harder to read from the timing.":"אליס מקלידה pwd. כל הקשה יוצאת מיד בחבילה מוצפנת משלה, והשרת שולח את התו בחזרה כדי שיוצג (ההד). מאז גרסה 9.5, OpenSSH שולח הקשות בקצב של 20 ms ומוסיף חבילות פיתיון, כך שקשה יותר לקרוא את קצב ההקלדה מהתזמון.","Per key":"לכל הקשה","1 packet, 90 bytes":"1 חבילה, 90 בתים",Echo:"הד","Sent back by the server":"נשלח בחזרה על ידי השרת",Timing:"תזמון","20 ms beat plus decoys":"קצב של 20 ms ועוד פיתיונות","Enter key":"מקש Enter","Client: KEX_ECDH_INIT (sntrup761x25519 public keys)":"לקוח: KEX_ECDH_INIT (מפתחות ציבוריים sntrup761x25519)","Server: KEX_ECDH_REPLY (host key, its half, signature)":"שרת: KEX_ECDH_REPLY (מפתח מארח, החצי שלו, חתימה)","Encrypted (len=44): service request, ssh-userauth":"מוצפן (len=44): בקשת שירות, ssh-userauth","Encrypted (len=44): service accept":"מוצפן (len=44): השירות התקבל","Encrypted (len=68): login with method none":"מוצפן (len=68): התחברות בשיטה none","Encrypted (len=52): try publickey,password":"מוצפן (len=52): נסו publickey,password","Encrypted (len=140): offer public key":"מוצפן (len=140): הצעת מפתח ציבורי","Encrypted (len=100): public key OK":"מוצפן (len=100): המפתח הציבורי בסדר","Encrypted (len=308): public key + signature":"מוצפן (len=308): מפתח ציבורי + חתימה","Encrypted (len=28): login success":"מוצפן (len=28): ההתחברות הצליחה","Encrypted (len=52): channel open: session":"מוצפן (len=52): פתיחת ערוץ: session","Encrypted (len=44): channel open confirmed":"מוצפן (len=44): פתיחת הערוץ אושרה","Encrypted (len=36): keystroke":"מוצפן (len=36): הקשה","Encrypted (len=36): echo":"מוצפן (len=36): הד","Encrypted (len=36): keystroke (Enter)":"מוצפן (len=36): הקשה (Enter)","Encrypted (len=132): output and a new prompt":"מוצפן (len=132): פלט ושורת פקודה חדשה","Packet length":"אורך חבילה","Bytes after this field.":"הבתים שאחרי השדה הזה.","Padding length":"אורך ריפוד","Random padding brings the packet to a multiple of 8 bytes.":"ריפוד אקראי מביא את החבילה לכפולה של 8 בתים.",Cookie:"Cookie","Host keys":"מפתחות מארח","Ciphers, out":"צפנים, יוצא","Ciphers, in":"צפנים, נכנס","MACs, out":"MAC, יוצא","Compression, out":"דחיסה, יוצא","Compression, in":"דחיסה, נכנס","Languages, out":"שפות, יוצא","Languages, in":"שפות, נכנס","First packet follows":"החבילה הראשונה באה אחריו",Reserved:"שמור","Public keys":"מפתחות ציבוריים","51 bytes: ssh-ed25519 public key":"51 בתים: מפתח ציבורי ssh-ed25519","Server’s half":"החצי של השרת","1071 bytes (sntrup761 ciphertext 1,039 + X25519 32)":"1071 בתים (טקסט מוצפן sntrup761 בגודל 1,039 + X25519 32)",Signature:"חתימה","83 bytes: ssh-ed25519 signature over the exchange":"83 בתים: חתימת ssh-ed25519 על ההחלפה","From the next packet on, this side encrypts.":"מהחבילה הבאה והלאה, הצד הזה מצפין.","SSH · encrypted packet":"SSH · חבילה מוצפנת","Encrypted packet":"חבילה מוצפנת","With chacha20-poly1305 even the length is encrypted; a 16-byte tag at the end shows any change.":"עם chacha20-poly1305 אפילו האורך מוצפן; תג של 16 בתים בסוף חושף כל שינוי.","SSH_MSG_USERAUTH_REQUEST (50): user “alice”, service “ssh-connection”, method “none”":"SSH_MSG_USERAUTH_REQUEST (50): משתמש ״alice״, שירות ״ssh-connection״, שיטה ״none״","SSH_MSG_USERAUTH_FAILURE (51): methods that can continue: “publickey,password”":"SSH_MSG_USERAUTH_FAILURE (51): שיטות שאפשר להמשיך בהן: ״publickey,password״","SSH_MSG_USERAUTH_REQUEST (50): method “publickey”, no signature, the ssh-ed25519 public key":"SSH_MSG_USERAUTH_REQUEST (50): שיטה ״publickey״, בלי חתימה, המפתח הציבורי ssh-ed25519","SSH_MSG_USERAUTH_PK_OK (60): the same ssh-ed25519 key":"SSH_MSG_USERAUTH_PK_OK (60): אותו מפתח ssh-ed25519","SSH_MSG_USERAUTH_REQUEST (50): method “publickey-hostbound-v00@openssh.com”, the key, the server’s host key and a signature":"SSH_MSG_USERAUTH_REQUEST (50): שיטה ״publickey-hostbound-v00@openssh.com״, המפתח, מפתח המארח של השרת וחתימה","SSH_MSG_CHANNEL_OPEN (90): “session”, channel 0, window 2 MB, packets up to 32 KB":"SSH_MSG_CHANNEL_OPEN (90): ״session״, ערוץ 0, חלון 2 MB, חבילות עד 32 KB","SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): channel 0 is open":"SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): ערוץ 0 פתוח","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”":"SSH_MSG_CHANNEL_DATA (94), ערוץ 0: 1 בית, ״p״","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), ערוץ 0: 1 בית, ״p״, נשלח בחזרה כדי שיוצג","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”":"SSH_MSG_CHANNEL_DATA (94), ערוץ 0: 1 בית, ״w״","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), ערוץ 0: 1 בית, ״w״, נשלח בחזרה כדי שיוצג","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”":"SSH_MSG_CHANNEL_DATA (94), ערוץ 0: 1 בית, ״d״","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), ערוץ 0: 1 בית, ״d״, נשלח בחזרה כדי שיוצג","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, a carriage return (Enter)":"SSH_MSG_CHANNEL_DATA (94), ערוץ 0: 1 בית, תו חזרת גררה (Enter)","SSH_MSG_CHANNEL_DATA (94), channel 0: 94 bytes: a new line, the shell’s terminal codes, “/home/alice”, and the coloured prompt":"SSH_MSG_CHANNEL_DATA (94), ערוץ 0: 94 בתים: שורה חדשה, קודי המסוף של המעטפת, ״/home/alice״, ושורת הפקודה הצבעונית","Encryption Explained":"הצפנה בהסבר","From browser":"מהדפדפן","TLS puts a secure channel on top of TCP. It proves the server’s identity with a certificate, agrees on fresh keys, then encrypts and authenticates everything sent. HTTPS, secure email and many other protocols run inside it. SSL was the name of its predecessor.":"TLS מניח ערוץ מאובטח מעל TCP. הוא מוכיח את זהות השרת בעזרת תעודה, מסכם על מפתחות חדשים, ואז מצפין ומאמת כל מה שנשלח. HTTPS, דואר מאובטח ופרוטוקולים רבים אחרים רצים בתוכו. SSL היה שמו של קודמו.",Sits:"ממוקם","Between TCP and the app":"בין TCP לאפליקציה","OSI layer":"שכבת OSI","Often placed at 6":"לרוב משויך לשכבה 6",Current:"נוכחי",Retired:"הוצא משימוש","SSL 2 and 3, TLS 1.0 and 1.1":"SSL 2 ו־3, TLS 1.0 ו־1.1","The app’s own (443, 993 …)":"של האפליקציה עצמה (443, 993 …)","Secure from start to finish":"מאובטח מתחילתו ועד סופו","One round trip to set up":"סבב אחד להקמה","One round trip agreed on a version, a cipher and a post-quantum hybrid key. The certificate chain proved who the server was, and every byte after the Server Hello was encrypted and authenticated, right up to the close_notify. Press REPLAY to watch it again.":"סבב אחד הלוך ושוב הספיק כדי להסכים על גרסה, צופן ומפתח היברידי פוסט־קוונטי. שרשרת התעודות הוכיחה מי השרת, וכל בית אחרי ה־Server Hello היה מוצפן ומאומת, עד ה־close_notify. לחצו על ״שוב״ כדי לצפות שוב.","1 round trip":"סבב אחד","Everything the browser supports":"כל מה שהדפדפן תומך בו","After the TCP handshake the browser lists what it can do: TLS versions, cipher suites, and key shares for the groups it expects, including the post-quantum hybrid X25519MLKEM768. It also names the site (SNI) and the protocols it speaks (ALPN).":"אחרי לחיצת היד של TCP הדפדפן מפרט מה הוא יודע לעשות: גרסאות TLS, חבילות הצפנה ושיתופי מפתח לקבוצות שהוא מצפה להן, כולל ההיברידית הפוסט־קוונטית X25519MLKEM768. הוא גם מציין את שם האתר (SNI) ואת הפרוטוקולים שהוא מדבר (ALPN).",Versions:"גרסאות","versions, ciphers, key shares":"גרסאות, צפנים, שיתופי מפתח","Choices made, keys computed":"הבחירות נעשו, המפתחות חושבו","The server picks TLS 1.3, the cipher suite and the hybrid group, and sends its own key share. From the two shares both sides compute the same secret without it ever crossing the network. Everything after this message is encrypted.":"השרת בוחר TLS 1.3, את חבילת ההצפנה ואת הקבוצה ההיברידית, ושולח את שיתוף המפתח שלו. משני השיתופים שני הצדדים מחשבים את אותו סוד, בלי שהוא יעבור אי־פעם ברשת. כל מה שאחרי ההודעה הזו מוצפן.",Group:"קבוצה","From here on":"מכאן והלאה","its key share":"שיתוף המפתח שלו",Certificate:"תעודה","Who the server is, proven":"מי השרת, מוכח","Now encrypted, the flight continues: the chosen protocol (http/1.1), the certificate chain, a signature made with the certificate’s private key, and Finished.":"עכשיו בהצפנה, סדרת ההודעות נמשכת: הפרוטוקול שנבחר (http/1.1), שרשרת התעודות, חתימה שנעשתה עם המפתח הפרטי של התעודה, ו־Finished.",Chain:"שרשרת","Site → intermediate → root":"אתר ← ביניים ← שורש","Proves the private key":"מוכיח את המפתח הפרטי",Checked:"נבדק","Name, dates, trusted root":"שם, תאריכים, שורש מהימן","encrypted: http/1.1, certificates,":"מוצפן: http/1.1, תעודות,","signature, Finished":"חתימה, Finished","One round trip, then data":"סבב אחד, ואז נתונים","The browser sends its own Finished: a check value over everything both sides said, keyed with the new secret, so any tampering with the hellos would show. TLS 1.3 needs one round trip before data flows; TLS 1.2 needed two.":"הדפדפן שולח Finished משלו: ערך ביקורת על כל מה ששני הצדדים אמרו, במפתח של הסוד החדש, כך שכל שינוי בהודעות ה־hello היה מתגלה. TLS 1.3 צריך סבב אחד לפני שנתונים זורמים; TLS 1.2 היה צריך שניים.",Covers:"מכסה","The whole handshake":"כל לחיצת היד","For old middleboxes":"עבור התקני ביניים ישנים","check value over":"ערך ביקורת על","the whole handshake":"כל לחיצת היד","Encrypted Data":"נתונים מוצפנים","Records, tags and tickets":"רשומות, תגים וכרטיסים","HTTP now travels in encrypted records, each with a 16-byte tag that exposes any change. The server also sends two session tickets: next time the browser can resume with one and skip the certificate.":"HTTP נוסע עכשיו ברשומות מוצפנות, לכל אחת תג של 16 בתים שחושף כל שינוי. השרת גם שולח שני כרטיסי סשן: בפעם הבאה הדפדפן יוכל לחדש את הסשן עם אחד מהם ולדלג על התעודה.","Per record":"לכל רשומה","22 bytes of overhead":"22 בתים של תקורה","2, for resuming later":"2, לחידוש מאוחר יותר",Visible:"מה גלוי","IPs, SNI, sizes, timing":"כתובות IP, SNI, גדלים, תזמון","2 session tickets":"2 כרטיסי סשן","for resuming later":"לחידוש מאוחר יותר",Closing:"סגירה","close_notify, then TCP":"close_notify, ואז TCP","After 75 idle seconds the server closes the connection. It first sends a close_notify alert, encrypted like everything else, so the browser knows the data ended on purpose and wasn’t cut short by an attacker. Then TCP closes as usual.":"אחרי 75 שניות ללא פעילות השרת סוגר את החיבור. קודם הוא שולח התראת close_notify, מוצפנת כמו כל השאר, כדי שהדפדפן יידע שהנתונים הסתיימו בכוונה ולא נקטעו על ידי תוקף. אחר כך TCP נסגר כרגיל.",Alert:"התראה","Shows nothing was cut off":"מראה ששום דבר לא נקטע","TCP FIN from both sides":"TCP FIN משני הצדדים","alert: close_notify":"התראה: close_notify",encrypted:"מוצפן","Server Hello, Change Cipher Spec (+ encrypted)":"Server Hello, Change Cipher Spec (+ מוצפן)","Encrypted handshake (continued)":"לחיצת יד מוצפנת (המשך)","Encrypted handshake (certificate, verify, Finished)":"לחיצת יד מוצפנת (תעודה, אימות, Finished)","Application Data (inside: close_notify alert)":"Application Data (בפנים: התראת close_notify)","Alert: close_notify (the data ends here, on purpose)":"התראה: close_notify (הנתונים מסתיימים כאן, בכוונה)","No IP address":"אין כתובת IP","192.168.1.1 · DHCP server":"192.168.1.1 · שרת DHCP"},a=s=>s==="1"?"רשומה אחת":`${s} רשומות`,d={strings:{...i,...n},patterns:[[/^([\d,]+) bytes$/,"$1 בתים"],[/^(Ethernet II|IPv4|UDP|TCP) · (\d+) bytes$/,"$1 · $2 בתים"],[/^(Application Data|Handshake|Change Cipher Spec), ([\d,]+) bytes?$/,(s,e,t)=>`${e}, ${t==="1"?"בית אחד":`${t} בתים`}`],[/^([\d,]+) bytes: report\.pdf, bytes (.+)$/,"$1 בתים: report.pdf, בתים $2"],[/^(.+) h later$/,"כעבור $1 שעות"],[/^(.+) min later$/,"כעבור $1 דקות"],[/^(.+) s later$/,"כעבור $1 שניות"],[/^(\S+) \(relative\)$/,"$1 (יחסי)"],[/^(\d+) \(ephemeral\)$/,"$1 (זמני)"],[/^(\d+) TCP segments$/,"$1 מקטעי TCP"],[/^(\d+) segments$/,"$1 מקטעים"],[/^(.*), (\d+) segments$/,"$1, $2 מקטעים"],[/^TLS 1\.3 · (\d+) records? · bytes (.+) of (.+)$/,(s,e,t,r)=>`TLS 1.3 · ${a(e)} · בתים ${t} מתוך ${r}`],[/^TLS 1\.3 · (\d+) records?$/,(s,e)=>`TLS 1.3 · ${a(e)}`],[/^Ethernet padding · (\d+) bytes$/,"ריפוד Ethernet · $1 בתים"],[/^(\d+) zero bytes, up to the 300-byte minimum$/,"$1 בתים של אפסים, עד המינימום של 300 בתים"],[/^(\d+) zero bytes$/,"$1 בתים של אפסים"],[/^(\d+) random bytes$/,"$1 בתים אקראיים"],[/^Seen as it leaves (.+)$/,"כפי שנראתה ביציאה מ־$1"],[/^Option (\d+)$/,"אפשרות $1"],[/^value (\d+), echo (\d+)$/,"ערך $1, הד $2"],[/^20 bytes, plus (\d+) of options\.$/,"20 בתים, ועוד $1 של אפשרויות."],[/^Windows starts at (\d+)\. Set to (\d+) on purpose here\.$/,"Windows מתחיל ב־$1. כאן הוגדר ל־$2 בכוונה."],[/^Started at (\d+); (\d+) routers? on the way each took 1\.$/,(s,e,t)=>t==="1"?`התחיל ב־${e}; הנתב היחיד בדרך הוריד 1.`:`התחיל ב־${e}; כל אחד מ־${t} הנתבים בדרך הוריד 1.`],[/^all (\d+) bytes of it$/,"כל $1 הבתים שלה"],[/^The packet that caused this, as the reporting device received it \(TTL (\d+)\), so the sender can tell which packet it was\.$/,"החבילה שגרמה לכך, כפי שהמכשיר המדווח קיבל אותה (TTL $1), כדי שהשולח יוכל לזהות באיזו חבילה מדובר."],[/^Port (\d+), TLS from the start$/,"פורט $1, TLS מההתחלה"],[/^(\d+), TLS from the start$/,"$1, TLS מההתחלה"]],post:o};export{d as default};
